insert into public.muscle_groups(code,name,parent_code,sort_order) values
('glutes_medius','Средняя ягодичная','glutes',111),
('adductors','Приводящие бедра',null,115),
('erectors','Разгибатели спины','back',22)
on conflict(code) do update set name=excluded.name,parent_code=excluded.parent_code,sort_order=excluded.sort_order;

insert into public.movement_patterns(code,name,sort_order) values
('chest_fly','Сведение рук на грудь',25),
('lat_isolation','Изоляция широчайших',55),
('knee_extension','Разгибание колена',95),
('hip_thrust','Ягодичный мост / hip thrust',75),
('hip_extension','Разгибание бедра',76),
('hip_abduction','Отведение бедра',77),
('hip_adduction','Приведение бедра',78),
('core_anti_extension','Кор: антиразгибание',151),
('core_hip_flexion','Кор: подъём ног / таза',152),
('back_extension','Разгибание корпуса',171),
('wrist_flexion','Сгибание запястья',180),
('wrist_extension','Разгибание запястья',181)
on conflict(code) do update set name=excluded.name,sort_order=excluded.sort_order;

-- "Верх груди" больше не отдельная мышца: сохраняем угол в паттерне движения.
insert into public.exercise_muscle_groups(exercise_id,muscle_group_code,role)
select exercise_id,'chest',role
from public.exercise_muscle_groups
where muscle_group_code='chest_upper'
on conflict(exercise_id,muscle_group_code) do update set role=
case when excluded.role='primary' then 'primary' else public.exercise_muscle_groups.role end;

delete from public.exercise_muscle_groups where muscle_group_code='chest_upper';
delete from public.muscle_groups where code='chest_upper';

with data as (
  select *
  from jsonb_to_recordset('[{"code":"CHEST_FLAT_DB_PRESS","name":"Жим гантелей лёжа на горизонтальной скамье","type":"compound","track":"weight_reps","eq":"dumbbell","pat":"horizontal_push","rest":150,"uni":false,"aliases":["Жим гантелей лёжа"],"p":["chest"],"s":["delts_front","triceps"],"st":[],"d":"Базовый жим на грудь со свободной траекторией каждой руки. Позволяет подобрать удобное положение локтей и хорошо подходит для прогрессии нагрузки.","i":"Сведи и опусти лопатки, устойчиво поставь стопы. Опускай гантели к линии середины груди до комфортного растяжения, затем выжимай вверх без удара гантелей друг о друга.","setup":"Скамья горизонтальна; предплечья близки к вертикали в нижней точке; локти не разводи строго в стороны.","mist":"Плечи уходят вперёд; чрезмерно глубокое опускание; отбив; потеря опоры стопами."},{"code":"CHEST_FLAT_BB_PRESS","name":"Жим штанги лёжа","type":"compound","track":"weight_reps","eq":"barbell","pat":"horizontal_push","rest":180,"uni":false,"aliases":["Жим штанги на горизонтальной скамье"],"p":["chest"],"s":["delts_front","triceps"],"st":[],"d":"Классический базовый жим для груди, трицепса и передней дельты. Особенно удобен для точной прогрессии нагрузки.","i":"Сними штангу на прямых руках, опусти к середине или нижней части груди и выжми вверх по устойчивой траектории. Сохраняй лопатки сведёнными и опущенными.","setup":"Хват обычно немного шире плеч; стопы плотно на полу; запястья над локтями.","mist":"Отбив от груди; локти строго в стороны; отрыв таза; потеря напряжения верхней части спины."},{"code":"CHEST_FLAT_SMITH_PRESS","name":"Жим в Смите лёжа","type":"compound","track":"weight_reps","eq":"smith","pat":"horizontal_push","rest":150,"uni":false,"aliases":["Жим в Смите на горизонтальной скамье"],"p":["chest"],"s":["delts_front","triceps"],"st":[],"d":"Горизонтальный жим с фиксированной траекторией. Удобен для стабильной работы близко к отказу без необходимости балансировать штангу.","i":"Расположи скамью так, чтобы гриф опускался к середине груди. Подконтрольно опускай и выжимай, не меняя положения плеч.","setup":"Проверь траекторию пустым грифом; лопатки сведены и опущены; стопы устойчивы.","mist":"Неправильное положение скамьи; плечи уходят вперёд; слишком узкая или широкая постановка рук."},{"code":"CHEST_MACHINE_PRESS","name":"Жим от груди в тренажёре","type":"compound","track":"weight_reps","eq":"machine","pat":"horizontal_push","rest":120,"uni":false,"aliases":["Chest press","Жим на грудь в тренажёре"],"p":["chest"],"s":["delts_front","triceps"],"st":[],"d":"Стабильный жим на грудь в тренажёре. Хорош для набора объёма и работы близко к отказу, когда баланс свободного веса не нужен.","i":"Прижми спину к опоре, держи плечи опущенными. Опускай рукояти до комфортного растяжения груди и выжимай без полного расслабления внизу.","setup":"Настрой сиденье так, чтобы рукояти находились примерно на уровне середины груди.","mist":"Слишком высокая посадка; плечи тянутся к ушам; сокращённая амплитуда; отрыв спины."},{"code":"CHEST_INCLINE_MACHINE_PRESS","name":"Наклонный жим на грудь в тренажёре","type":"compound","track":"weight_reps","eq":"machine","pat":"incline_push","rest":120,"uni":false,"aliases":["Наклонный chest press"],"p":["chest"],"s":["delts_front","triceps"],"st":[],"d":"Стабильный наклонный жим с несколько большим акцентом на ключичную часть большой грудной. Отдельную мышцу «верх груди» для этого создавать не нужно.","i":"Прижми корпус к спинке, опускай рукояти подконтрольно и выжимай вперёд-вверх. Сохраняй плечи опущенными и не укорачивай нижнюю часть амплитуды.","setup":"Высота сиденья должна позволять начать движение без чрезмерного подъёма плеч.","mist":"Слишком вертикальный угол; движение только передней дельтой; отрыв корпуса; короткая амплитуда."},{"code":"CHEST_PUSHUP","name":"Отжимания от пола","type":"compound","track":"bodyweight_reps","eq":"bodyweight","pat":"horizontal_push","rest":90,"uni":false,"aliases":["Отжимания"],"p":["chest"],"s":["delts_front","triceps"],"st":["core"],"d":"Доступный жим собственным весом для груди, трицепса и передней дельты. Нагрузку можно менять темпом, высотой опоры и дополнительным весом.","i":"Держи корпус одной линией, опускай грудь между ладонями и выжимай пол от себя. Лопатки в верхней точке могут естественно двигаться вперёд.","setup":"Ладони немного шире плеч; пальцы вперёд или слегка наружу; корпус напряжён.","mist":"Провисание таза; локти строго в стороны; неполная амплитуда; голова тянется к полу раньше груди."},{"code":"CHEST_CABLE_FLY","name":"Сведение рук в кроссовере","type":"isolation","track":"weight_reps","eq":"cable","pat":"chest_fly","rest":75,"uni":false,"aliases":["Кроссовер на грудь","Сведения на блоках"],"p":["chest"],"s":["delts_front"],"st":[],"d":"Изолирующее приведение плеча с постоянным сопротивлением троса. Удобно для контролируемой работы груди без большого участия трицепса.","i":"Сохраняя небольшой сгиб в локтях, своди руки перед корпусом по дуге и медленно возвращай до комфортного растяжения.","setup":"Стой устойчиво между блоками; плечи опущены; корпус слегка наклонён вперёд.","mist":"Сгибание и разгибание локтей вместо сведения; чрезмерное растяжение плеча; рывки корпусом."},{"code":"CHEST_PEC_DECK","name":"Сведение рук в тренажёре Peck Deck","type":"isolation","track":"weight_reps","eq":"machine","pat":"chest_fly","rest":75,"uni":false,"aliases":["Бабочка на грудь","Pec deck"],"p":["chest"],"s":["delts_front"],"st":[],"d":"Изолирующее упражнение на грудь с фиксированной и легко контролируемой траекторией. Удобно для стабильного объёма и работы близко к отказу.","i":"Сведи рукояти перед собой, не меняя угол в локтях, задержись в сокращении и подконтрольно верни руки назад.","setup":"Настрой сиденье так, чтобы плечевой сустав и рукояти находились на комфортной линии.","mist":"Плечи поднимаются к ушам; чрезмерное растяжение; быстрый возврат веса; движение локтями за счёт трицепса."},{"code":"BACK_LAT_MEDIUM_PRONATED_PULL","name":"Тяга верхнего блока прямым хватом к груди","type":"compound","track":"weight_reps","eq":"cable","pat":"vertical_pull","rest":120,"uni":false,"aliases":["Тяга верхнего блока средним прямым хватом"],"p":["lats"],"s":["back_mid","biceps"],"st":[],"d":"Базовая вертикальная тяга прямым хватом. По назначению близка к другим вариантам хвата, поэтому прежде всего служит альтернативой по удобству.","i":"Подними грудь, опусти плечи и тяни перекладину к верхней части груди, направляя локти вниз. Возвращай вес до контролируемого растяжения.","setup":"Хват примерно 1–1,5 ширины плеч; корпус почти вертикален или слегка отклонён назад.","mist":"Тяга за голову; сильная раскачка; тяга только руками; неполное растяжение."},{"code":"BACK_LAT_SUPINATED_PULL","name":"Тяга верхнего блока обратным хватом","type":"compound","track":"weight_reps","eq":"cable","pat":"vertical_pull","rest":120,"uni":false,"aliases":["Тяга верхнего блока супинированным хватом"],"p":["lats"],"s":["biceps","back_mid"],"st":[],"d":"Вертикальная тяга обратным хватом с заметным участием сгибателей локтя. Полезна как комфортная альтернатива прямому и нейтральному хвату.","i":"Тяни рукоять к верхней части груди, ведя локти вниз и немного назад. Не превращай движение в сильный наклон корпуса.","setup":"Хват около ширины плеч; ладони к себе; запястья держи нейтрально.","mist":"Слишком узкий хват; заламывание запястий; раскачка; сокращённая амплитуда."},{"code":"BACK_LAT_CLOSE_NEUTRAL_PULL","name":"Тяга верхнего блока узким нейтральным хватом","type":"compound","track":"weight_reps","eq":"cable","pat":"vertical_pull","rest":120,"uni":false,"aliases":["Тяга верхнего блока V-рукоятью"],"p":["lats"],"s":["biceps","back_mid"],"st":[],"d":"Комфортная вертикальная тяга с нейтральным положением кистей. Часто позволяет использовать хорошую амплитуду и подходит тем, кому неудобен широкий прямой хват.","i":"Тяни рукоять к верхней части груди, локти направляй вниз вдоль корпуса. В верхней точке дай широчайшим растянуться без потери контроля плеч.","setup":"Корпус почти вертикален; грудь слегка поднята; плечи не тянуть к ушам.","mist":"Сильный наклон назад; тяга только бицепсом; отсутствие растяжения; рывки."},{"code":"BACK_LAT_PRONATED_PULLUP","name":"Подтягивания прямым хватом","type":"compound","track":"bodyweight_reps","eq":"bodyweight","pat":"vertical_pull","rest":180,"uni":false,"aliases":["Подтягивания обычным хватом"],"p":["lats"],"s":["back_mid","biceps"],"st":["core"],"d":"Классическая вертикальная тяга собственным весом. Хорошо развивает широчайшие и общую силу тягового паттерна.","i":"Начни из контролируемого виса, опусти плечи и подтягивай грудь к перекладине, ведя локти вниз. Опускайся без броска.","setup":"Хват немного шире плеч; корпус собран; ноги не используются для раскачки.","mist":"Киппинг; вытягивание шеи; неполное опускание; чрезмерно широкий хват."},{"code":"BACK_LAT_CHINUP","name":"Подтягивания обратным хватом","type":"compound","track":"bodyweight_reps","eq":"bodyweight","pat":"vertical_pull","rest":180,"uni":false,"aliases":["Chin-up","Подтягивания супинированным хватом"],"p":["lats"],"s":["biceps","back_mid"],"st":["core"],"d":"Подтягивание с ладонями к себе. Сохраняет работу широчайших, но обычно сильнее вовлекает бицепс и может быть удобнее некоторым клиентам.","i":"Подтягивай грудь вверх, направляя локти вниз и назад. Полностью контролируй нижнюю часть амплитуды.","setup":"Хват примерно на ширине плеч; запястья нейтральны; без раскачки.","mist":"Рывок ногами; чрезмерное запрокидывание головы; неполный диапазон; боль в кистях из-за неудобной ширины."},{"code":"BACK_MID_BB_ROW","name":"Тяга штанги в наклоне","type":"compound","track":"weight_reps","eq":"barbell","pat":"horizontal_pull","rest":180,"uni":false,"aliases":["Тяга штанги к поясу"],"p":["back_mid"],"s":["lats","biceps"],"st":["core","erectors"],"d":"Базовая горизонтальная тяга со свободным весом. Нагружает середину спины и широчайшие, одновременно требуя удерживать корпус в наклоне.","i":"Зафиксируй наклон корпуса и тяни штангу к нижним рёбрам или верхней части живота. Опускай до полного контроля, не меняя угол корпуса каждым повторением.","setup":"Стопы устойчивы; спина нейтральна; колени слегка согнуты; штанга близко к ногам.","mist":"Раскачка корпусом; округление поясницы; слишком вертикальное положение; подъём плеч."},{"code":"BACK_MID_CHEST_SUPPORTED_DB_ROW","name":"Тяга гантелей с опорой грудью на наклонной скамье","type":"compound","track":"weight_reps","eq":"dumbbell","pat":"horizontal_pull","rest":120,"uni":false,"aliases":["Тяга гантелей лёжа грудью на скамье"],"p":["back_mid"],"s":["lats","biceps","delts_rear"],"st":[],"d":"Горизонтальная тяга с опорой грудью, почти убирающая ограничение со стороны поясницы. Удобна для точной нагрузки на мышцы спины.","i":"Прижми грудь к скамье и тяни гантели назад, сводя лопатки в комфортной амплитуде. Медленно опускай руки до растяжения.","setup":"Скамья примерно 20–45°; шея нейтральна; ноги устойчиво на полу.","mist":"Отрыв груди от скамьи; рывок; подъём плеч к ушам; чрезмерное сгибание кистей."},{"code":"BACK_MID_MACHINE_ROW","name":"Горизонтальная тяга в тренажёре с упором грудью","type":"compound","track":"weight_reps","eq":"machine","pat":"horizontal_pull","rest":120,"uni":false,"aliases":["Тяга сидя в тренажёре на спину"],"p":["back_mid"],"s":["lats","biceps","delts_rear"],"st":[],"d":"Стабильная горизонтальная тяга с минимальной нагрузкой на поясницу. Хороша для безопасной прогрессии и работы близко к отказу.","i":"Сохраняя грудь на упоре, тяни рукояти к корпусу и веди локти назад. Возвращай вес до контролируемого растяжения.","setup":"Настрой сиденье и упор так, чтобы плечи свободно двигались без подъёма к ушам.","mist":"Отрыв груди; короткая амплитуда; рывки; чрезмерное сведение лопаток при потере положения плеча."},{"code":"BACK_LAT_STRAIGHT_ARM_PULLDOWN","name":"Тяга прямыми руками на верхнем блоке","type":"isolation","track":"weight_reps","eq":"cable","pat":"lat_isolation","rest":75,"uni":false,"aliases":["Пуловер на блоке","Straight-arm pulldown"],"p":["lats"],"s":["triceps"],"st":["core"],"d":"Почти односуставное разгибание плеча с акцентом на широчайшие и небольшим вкладом бицепса. Хорошо подходит как дополнительное упражнение после тяг.","i":"Слегка согни локти и веди рукоять дугой от уровня головы к бёдрам, не меняя угол в локте. Медленно вернись до растяжения широчайших.","setup":"Корпус слегка наклонён; рёбра под контролем; трос свободно проходит перед телом.","mist":"Превращение в трицепсовое разгибание; чрезмерный прогиб; раскачка; слишком большой вес."},{"code":"DELTS_PRESS_DB_SEATED","name":"Жим гантелей сидя над головой","type":"compound","track":"weight_reps","eq":"dumbbell","pat":"vertical_push","rest":150,"uni":false,"aliases":["Жим гантелей сидя на плечи"],"p":["delts_front"],"s":["delts_side","triceps"],"st":["core"],"d":"Базовый вертикальный жим для передней дельты и трицепса со свободной траекторией рук. Часто комфортнее штанги для плечевого сустава.","i":"Начни с гантелей около уровня плеч и выжимай вверх, сохраняя рёбра и таз стабильными. Опускай до комфортной глубины.","setup":"Спинка почти вертикальна; стопы устойчивы; кисти можно держать нейтрально или слегка развернуть.","mist":"Сильный прогиб поясницы; слишком глубокое опускание при дискомфорте; удар гантелей наверху; плечи к ушам."},{"code":"DELTS_PRESS_BB","name":"Жим штанги стоя над головой","type":"compound","track":"weight_reps","eq":"barbell","pat":"vertical_push","rest":180,"uni":false,"aliases":["Армейский жим","Overhead press"],"p":["delts_front"],"s":["delts_side","triceps"],"st":["core","glutes"],"d":"Классический вертикальный жим, развивающий плечевой пояс и общую силу верхней части тела. Требует хорошего контроля корпуса.","i":"Выжимай штангу от верхней части груди вверх, слегка убирая голову с траектории, затем возвращай её под гриф. Не компенсируй движение разгибанием поясницы.","setup":"Хват чуть шире плеч; предплечья близки к вертикали; ягодицы и пресс напряжены.","mist":"Сильный прогиб; толчок ногами без задачи делать push press; локти слишком далеко назад; потеря контроля внизу."},{"code":"DELTS_PRESS_MACHINE","name":"Жим вверх в тренажёре","type":"compound","track":"weight_reps","eq":"machine","pat":"vertical_push","rest":120,"uni":false,"aliases":["Жим на плечи в тренажёре"],"p":["delts_front"],"s":["delts_side","triceps"],"st":[],"d":"Стабильный вертикальный жим для плеч и трицепса. Хороший вариант для набора тренировочного объёма без требований к балансу.","i":"Прижми корпус к спинке, выжимай рукояти вверх и подконтрольно опускай до комфортной глубины.","setup":"Настрой сиденье так, чтобы рукояти начинали примерно на уровне плеч или чуть ниже.","mist":"Отрыв поясницы; плечи к ушам; слишком низкая посадка; неполная амплитуда ради веса."},{"code":"DELTS_PRESS_SMITH","name":"Жим в Смите над головой сидя","type":"compound","track":"weight_reps","eq":"smith","pat":"vertical_push","rest":150,"uni":false,"aliases":["Жим на плечи в Смите"],"p":["delts_front"],"s":["delts_side","triceps"],"st":[],"d":"Вертикальный жим по фиксированной траектории. Удобен для стабильной прогрессии и тренировки близко к отказу.","i":"Расположи скамью так, чтобы гриф двигался перед лицом и опускался к уровню подбородка или верхней груди без дискомфорта.","setup":"Спинка почти вертикальна; проверь траекторию пустым грифом; стопы устойчивы.","mist":"Скамья стоит слишком далеко; чрезмерный прогиб; опускание за голову; слишком широкий хват."},{"code":"DELTS_REAR_DB_FLY","name":"Разведение гантелей в наклоне на заднюю дельту","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"rear_delt","rest":75,"uni":false,"aliases":["Махи гантелей в наклоне"],"p":["delts_rear"],"s":["back_mid"],"st":["core"],"d":"Простое упражнение на заднюю дельту со свободным весом. Может выполняться стоя, сидя или с опорой грудью.","i":"Зафиксируй наклон корпуса и разводи руки в стороны по дуге, сохраняя небольшой сгиб локтей. Опускай гантели медленно.","setup":"Корпус наклонён; шея нейтральна; плечи опущены.","mist":"Тяга гантелей локтями назад вместо разведения; раскачка; слишком тяжёлый вес; чрезмерное сведение лопаток."},{"code":"BICEPS_DB_CURL","name":"Сгибание рук с гантелями стоя","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"elbow_flexion","rest":90,"uni":false,"aliases":["Подъём гантелей на бицепс"],"p":["biceps"],"s":["forearms"],"st":["core"],"d":"Базовое сгибание локтя с независимой работой рук. Универсальный вариант для большинства залов.","i":"Сгибай локоть без движения плеча вперёд и медленно опускай гантель до почти полного разгибания. Можно супинировать кисть по мере подъёма.","setup":"Корпус устойчив; локти рядом с туловищем; запястья нейтральны.","mist":"Раскачка; локти уходят вперёд; сокращённая нижняя амплитуда; заламывание кисти."},{"code":"BICEPS_BB_CURL","name":"Сгибание рук со штангой стоя","type":"isolation","track":"weight_reps","eq":"barbell","pat":"elbow_flexion","rest":90,"uni":false,"aliases":["Подъём штанги на бицепс"],"p":["biceps"],"s":["forearms"],"st":["core"],"d":"Классическое двустороннее сгибание на бицепс, удобное для постепенного увеличения веса.","i":"Подними штангу сгибанием локтей, сохраняя плечи относительно неподвижными, затем медленно опусти до контролируемого растяжения.","setup":"Хват примерно на ширине плеч; корпус собран; локти близко к бокам.","mist":"Читинг корпусом; локти сильно вперёд; чрезмерно тяжёлый вес; неполное разгибание."},{"code":"BICEPS_EZ_CURL","name":"Сгибание рук с EZ-грифом стоя","type":"isolation","track":"weight_reps","eq":"barbell","pat":"elbow_flexion","rest":90,"uni":false,"aliases":["Подъём EZ-грифа на бицепс"],"p":["biceps"],"s":["forearms"],"st":["core"],"d":"Вариант подъёма штанги с более нейтральным положением кистей. Часто комфортнее прямого грифа для запястий и локтей.","i":"Сгибай локти без раскачки и контролируемо опускай гриф до почти полного разгибания.","setup":"Выбери удобный изгиб грифа; локти рядом с корпусом.","mist":"Раскачка; чрезмерное сгибание кистей; локти уходят вперёд; слишком быстрый негатив."},{"code":"BICEPS_CABLE_CURL","name":"Сгибание рук на нижнем блоке","type":"isolation","track":"weight_reps","eq":"cable","pat":"elbow_flexion","rest":75,"uni":false,"aliases":["Подъём на бицепс в кроссовере"],"p":["biceps"],"s":["forearms"],"st":[],"d":"Сгибание локтя с постоянным сопротивлением троса. Удобно для ровной техники и точной дозировки нагрузки.","i":"Сохраняй локти неподвижными, сгибай руки до полного контролируемого сокращения и медленно возвращай рукоять.","setup":"Встань достаточно далеко от блока, чтобы трос оставался натянутым внизу.","mist":"Движение плечом; раскачка; потеря натяжения внизу; заламывание запястий."},{"code":"BICEPS_INCLINE_DB_CURL","name":"Сгибание рук с гантелями на наклонной скамье","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"elbow_flexion","rest":90,"uni":false,"aliases":["Наклонные сгибания на бицепс"],"p":["biceps"],"s":["forearms"],"st":[],"d":"Сгибание локтя с плечом отведённым назад и хорошей нагрузкой в растянутом положении. Полезно как один из систематически чередуемых вариантов.","i":"Прижми спину к скамье, не выводи локоть вперёд и сгибай руку без раскачки. Полностью контролируй нижнюю позицию.","setup":"Скамья примерно 45–60°; руки свободно свисают вниз; плечи опущены.","mist":"Локти уходят вперёд; чрезмерное растяжение при дискомфорте; раскачка; быстрый негатив."},{"code":"BICEPS_PREACHER_CURL","name":"Сгибание рук на скамье Скотта","type":"isolation","track":"weight_reps","eq":"barbell","pat":"elbow_flexion","rest":90,"uni":false,"aliases":["Сгибания на скамье Скотта","Preacher curl"],"p":["biceps"],"s":["forearms"],"st":[],"d":"Сгибание локтя с фиксированным плечом, уменьшающее возможность читинга. Хорошо дополняет варианты, где плечо находится позади корпуса.","i":"Держи плечи на подушке, сгибай локти без отрыва рук и медленно разгибай почти до полного диапазона.","setup":"Подмышки близко к верхнему краю подушки; используй EZ-гриф или гантели, если кистям так удобнее.","mist":"Рывок из нижней точки; пассивная блокировка локтя под тяжёлым весом; отрыв плеч от опоры."},{"code":"BICEPS_HAMMER_CURL","name":"Молотковые сгибания с гантелями","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"elbow_flexion","rest":90,"uni":false,"aliases":["Молотки на бицепс"],"p":["biceps"],"s":["forearms"],"st":["core"],"d":"Сгибание локтя нейтральным хватом с большим вкладом плечевой и плечелучевой мышц. Практичный вариант для общей массы сгибателей локтя.","i":"Сохраняй ладони обращёнными друг к другу и сгибай локти без раскачки. Опускай гантели до контролируемого разгибания.","setup":"Локти рядом с корпусом; кисти нейтральны.","mist":"Мах корпусом; подъём плеч; локти уходят вперёд; слишком короткая амплитуда."},{"code":"TRICEPS_STRAIGHT_BAR_PUSHDOWN","name":"Разгибание рук на верхнем блоке с прямой рукоятью","type":"isolation","track":"weight_reps","eq":"cable","pat":"elbow_extension","rest":75,"uni":false,"aliases":["Разгибание на трицепс с прямой рукоятью"],"p":["triceps"],"s":[],"st":[],"d":"Классическое разгибание локтя на блоке с фиксированной рукоятью. Простая альтернатива канату, если так удобнее держать локти и кисти.","i":"Держи локти около корпуса и разгибай руки вниз до контролируемого сокращения, затем медленно вернись.","setup":"Корпус устойчив; плечи опущены; хват комфортной ширины.","mist":"Локти уходят вперёд; движение всем корпусом; чрезмерно тяжёлый вес; заламывание кистей."},{"code":"TRICEPS_SINGLE_ARM_PUSHDOWN","name":"Разгибание одной руки на верхнем блоке","type":"isolation","track":"weight_reps","eq":"cable","pat":"elbow_extension","rest":60,"uni":true,"aliases":["Одноручное разгибание на трицепс"],"p":["triceps"],"s":[],"st":[],"d":"Одностороннее разгибание локтя, позволяющее свободно подобрать положение кисти и сравнивать стороны.","i":"Зафиксируй плечо у корпуса и полностью разгибай локоть без движения плечом. Возвращай вес до комфортного сгибания.","setup":"Можно использовать рукоять или ремень; корпус не поворачивается.","mist":"Ротация корпуса; локоть гуляет; рывок; слишком большой вес."},{"code":"TRICEPS_CLOSE_GRIP_BENCH","name":"Жим штанги лёжа узким хватом","type":"compound","track":"weight_reps","eq":"barbell","pat":"horizontal_push","rest":150,"uni":false,"aliases":["Узкий жим на трицепс"],"p":["triceps"],"s":["chest","delts_front"],"st":[],"d":"Многосуставной жим с повышенным вкладом трицепса. Полезен как тяжёлый вариант, но не является полной биомеханической заменой изолирующим разгибаниям.","i":"Опускай штангу к нижней части груди, удерживая локти ближе к корпусу, и выжимай вверх без отбива.","setup":"Хват примерно на ширине плеч или немного уже; кисти над предплечьями; лопатки стабильны.","mist":"Слишком узкий хват; локти сильно в стороны; отбив; чрезмерная нагрузка на кисти."},{"code":"QUAD_BACK_SQUAT","name":"Приседания со штангой на спине","type":"compound","track":"weight_reps","eq":"barbell","pat":"squat","rest":180,"uni":false,"aliases":["Присед со штангой"],"p":["quads","glutes"],"s":["hamstrings"],"st":["core","erectors"],"d":"Базовое многосуставное упражнение для квадрицепса и ягодиц. Техника сильно зависит от антропометрии, мобильности и удобной стойки.","i":"Сядь вниз между стопами, сохраняя устойчивую опору всей стопой и колени по направлению носков. Поднимайся, одновременно разгибая колени и таз.","setup":"Ширина стоп индивидуальна; штанга стабильно лежит на верхе спины; вдох и брейс перед повтором.","mist":"Колени заваливаются внутрь; потеря опоры пяткой; расслабление корпуса; глубина ниже контролируемой позиции."},{"code":"QUAD_SMITH_SQUAT","name":"Приседания в Смите","type":"compound","track":"weight_reps","eq":"smith","pat":"squat","rest":150,"uni":false,"aliases":["Присед в машине Смита"],"p":["quads","glutes"],"s":["hamstrings"],"st":["core"],"d":"Присед с фиксированной траекторией, позволяющий меньше думать о балансе и легче дозировать нагрузку на ноги.","i":"Расположи стопы так, чтобы в нижней точке сохранялась устойчивость, затем приседай до комфортной глубины и вставай без отрыва стоп.","setup":"Проверь положение стоп пустым грифом; спина нейтральна; колени движутся по линии носков.","mist":"Стопы стоят слишком близко к траектории грифа; колени внутрь; таз подворачивается с потерей контроля."},{"code":"QUAD_LEG_EXTENSION","name":"Разгибание ног в тренажёре","type":"isolation","track":"weight_reps","eq":"machine","pat":"knee_extension","rest":75,"uni":false,"aliases":["Разгибание коленей в тренажёре"],"p":["quads"],"s":[],"st":[],"d":"Изолирующее разгибание колена для квадрицепса. Удобно для прямой нагрузки на квадрицепс без ограничения со стороны спины и ягодиц.","i":"Разгибай колени плавно до почти полного выпрямления и медленно опускай вес, сохраняя таз прижатым.","setup":"Ось колена совпадает с осью тренажёра; валик расположен над нижней частью голени.","mist":"Рывок; отрыв таза; бросание веса вниз; слишком большая нагрузка с потерей контроля."},{"code":"QUAD_REVERSE_LUNGE","name":"Обратные выпады с гантелями","type":"compound","track":"weight_reps","eq":"dumbbell","pat":"lunge","rest":120,"uni":true,"aliases":["Выпады назад"],"p":["quads","glutes"],"s":["hamstrings"],"st":["core"],"d":"Одностороннее упражнение на квадрицепс и ягодицы, обычно легче контролируемое, чем выпады вперёд. Хорошо подходит для сравнения сторон.","i":"Шагни назад, опусти колено к полу и вернись усилием передней ноги. Держи переднюю стопу полностью на полу.","setup":"Ширина шага должна позволять сохранять баланс и колено по линии стопы.","mist":"Отталкивание задней ногой; завал колена внутрь; слишком узкая линия стоп; падение корпуса."},{"code":"QUAD_WALKING_LUNGE","name":"Выпады в движении с гантелями","type":"compound","track":"weight_reps","eq":"dumbbell","pat":"lunge","rest":120,"uni":true,"aliases":["Ходьба выпадами"],"p":["quads","glutes"],"s":["hamstrings"],"st":["core"],"d":"Динамический односторонний вариант для ног и ягодиц, одновременно требующий координации и устойчивости.","i":"Сделай контролируемый шаг, опусти заднее колено и перенеси корпус вперёд в следующий выпад через усилие передней ноги.","setup":"Держи гантели вдоль корпуса; шаги одинаковой длины; сохраняй пространство между стопами по ширине.","mist":"Шаги по одной линии; колено внутрь; толчок задней ногой; слишком быстрый темп."},{"code":"HAMSTRING_RDL_BB","name":"Румынская тяга со штангой","type":"compound","track":"weight_reps","eq":"barbell","pat":"hinge","rest":180,"uni":false,"aliases":["Румынская тяга"],"p":["hamstrings","glutes"],"s":[],"st":["core","erectors"],"d":"Базовый тазовый шарнир для задней поверхности бедра и ягодиц. Хорошо прогрессируется по весу и нагружает мышцы в растянутом положении.","i":"Отводи таз назад при слегка согнутых коленях и веди штангу близко к ногам. Остановись там, где сохраняется нейтральная спина и выраженное растяжение задней поверхности бедра, затем разогни таз.","setup":"Стопы примерно на ширине таза; хват чуть шире ног; корпус собран.","mist":"Присед вместо наклона; штанга далеко от ног; округление спины; попытка обязательно коснуться пола."},{"code":"HAMSTRING_NORDIC_CURL","name":"Нордические сгибания","type":"isolation","track":"bodyweight_reps","eq":"bodyweight","pat":"knee_flexion","rest":120,"uni":false,"aliases":["Nordic curl"],"p":["hamstrings"],"s":[],"st":["core"],"d":"Тяжёлое сгибание колена собственным весом с большой эксцентрической нагрузкой на заднюю поверхность бедра. Подходит, если можно надёжно зафиксировать стопы.","i":"Сохраняя прямую линию от коленей до головы, медленно опускай корпус вперёд, сопротивляясь разгибанию коленей. Помоги руками внизу и вернись настолько активно, насколько позволяет сила.","setup":"Колени на мягкой опоре; пятки надёжно зафиксированы партнёром или оборудованием.","mist":"Сгибание в тазу; слишком быстрое падение; чрезмерный объём для неподготовленного клиента; ненадёжная фиксация стоп."},{"code":"GLUTE_HIP_THRUST_BB","name":"Ягодичный мост со штангой от скамьи","type":"compound","track":"weight_reps","eq":"barbell","pat":"hip_thrust","rest":150,"uni":false,"aliases":["Hip thrust со штангой","Хип-траст"],"p":["glutes"],"s":["hamstrings"],"st":["core"],"d":"Стабильное упражнение для целевой нагрузки большой ягодичной. Хорошо прогрессируется по весу и обычно мало ограничивается спиной.","i":"Опирайся верхом спины на скамью, опусти таз и разогни его до положения, где корпус и бедро образуют линию. Вверху слегка подкрути таз без переразгибания поясницы.","setup":"Гриф лежит на сгибе таза через мягкую накладку; стопы стоят так, чтобы вверху голени были близки к вертикали.","mist":"Переразгибание поясницы; стопы слишком далеко или близко; толчок носками; неполная нижняя амплитуда."},{"code":"GLUTE_HIP_THRUST_SMITH","name":"Ягодичный мост в Смите от скамьи","type":"compound","track":"weight_reps","eq":"smith","pat":"hip_thrust","rest":120,"uni":false,"aliases":["Hip thrust в Смите"],"p":["glutes"],"s":["hamstrings"],"st":["core"],"d":"Стабильный вариант hip thrust с фиксированной траекторией. Удобен для самостоятельной тренировки и работы близко к отказу.","i":"Опусти таз под контролем и разогни до полного сокращения ягодиц без прогиба поясницы. Сохраняй колени по линии стоп.","setup":"Скамья надёжно зафиксирована; гриф с мягкой накладкой; стопы симметричны.","mist":"Скамья скользит; переразгибание поясницы; колени внутрь; движение слишком короткое."},{"code":"GLUTE_CABLE_KICKBACK","name":"Отведение ноги назад на нижнем блоке","type":"isolation","track":"weight_reps","eq":"cable","pat":"hip_extension","rest":60,"uni":true,"aliases":["Кикбэк на ягодицы в кроссовере"],"p":["glutes"],"s":["hamstrings"],"st":["core"],"d":"Одностороннее разгибание бедра с постоянным сопротивлением троса. Подходит для дополнительной нагрузки ягодиц без тяжёлой осевой нагрузки.","i":"Сохраняя таз направленным вперёд, отводи бедро назад до сокращения ягодицы и медленно возвращай ногу.","setup":"Манжета на голени или лодыжке; корпус стабилен; опорная нога слегка согнута.","mist":"Прогиб поясницы; разворот таза; мах ногой; слишком большая амплитуда."},{"code":"GLUTE_BACK_EXTENSION_45","name":"Гиперэкстензия 45° с акцентом на ягодицы","type":"compound","track":"weight_reps","eq":"machine","pat":"hip_extension","rest":90,"uni":false,"aliases":["Гиперэкстензия на ягодицы"],"p":["glutes"],"s":["hamstrings"],"st":["erectors"],"d":"Разгибание таза на римском стуле с акцентом на ягодицы и заднюю поверхность бедра. Удобный дополнительный вариант без тяжёлой штанги.","i":"Отводи таз назад и опускай корпус за счёт тазобедренного сустава. Поднимайся сокращением ягодиц до нейтрального положения корпуса.","setup":"Край подушки находится ниже сгиба таза; стопы надёжно зафиксированы.","mist":"Переразгибание поясницы; движение позвоночником вместо таза; слишком высокая подушка; рывки."},{"code":"GLUTE_MACHINE_ABDUCTION","name":"Отведение бёдер в тренажёре","type":"isolation","track":"weight_reps","eq":"machine","pat":"hip_abduction","rest":60,"uni":false,"aliases":["Разведение ног в тренажёре"],"p":["glutes_medius"],"s":["glutes"],"st":[],"d":"Изолированное отведение бедра для средней ягодичной и других отводящих мышц. Не является обязательным для каждой программы, но удобно как дополнительная работа.","i":"Разводи бёдра плавно до комфортной амплитуды и медленно возвращай, сохраняя таз устойчивым.","setup":"Сядь устойчиво; настрой упоры так, чтобы движение начиналось без болезненного растяжения.","mist":"Рывки; чрезмерный наклон корпуса ради веса; быстрое схлопывание ног; слишком большая амплитуда."},{"code":"LEGS_MACHINE_ADDUCTION","name":"Приведение бёдер в тренажёре","type":"isolation","track":"weight_reps","eq":"machine","pat":"hip_adduction","rest":60,"uni":false,"aliases":["Сведение ног в тренажёре"],"p":["adductors"],"s":[],"st":[],"d":"Изолированное приведение бедра для приводящих мышц. Полезно как дополнительное упражнение, если в программе нужен прямой объём на внутреннюю поверхность бедра.","i":"Своди бёдра плавно до комфортного сокращения и медленно возвращай их наружу без рывка.","setup":"Настрой стартовую ширину так, чтобы не было болезненного растяжения в паху.","mist":"Резкое растяжение; бросание веса; чрезмерная стартовая ширина; отрыв таза от сиденья."},{"code":"CALVES_SINGLE_LEG_DB","name":"Подъём на носок одной ногой с гантелью","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"calf_raise","rest":60,"uni":true,"aliases":["Одноногий подъём на носок"],"p":["calves"],"s":[],"st":[],"d":"Доступный вариант тренировки икр с почти прямым коленом, не требующий специального тренажёра. Позволяет отдельно сравнивать силу сторон.","i":"Опускай пятку до комфортного растяжения и поднимайся максимально высоко на носок без пружинящих движений.","setup":"Передняя часть стопы на устойчивой платформе; свободной рукой можно держаться за опору.","mist":"Пружинящий темп; сгибание колена; разворот стопы; сокращённая амплитуда."},{"code":"CORE_PLANK","name":"Планка на предплечьях","type":"isolation","track":"duration","eq":"bodyweight","pat":"core_anti_extension","rest":60,"uni":false,"aliases":["Планка"],"p":["core"],"s":[],"st":["glutes"],"d":"Изометрическое упражнение на сопротивление разгибанию поясницы. Подходит для базового контроля корпуса и не требует оборудования.","i":"Сожми ягодицы, слегка подкрути таз и удерживай рёбра над тазом. Дыши, не теряя положения корпуса.","setup":"Локти под плечами; ноги прямые; тело образует ровную линию.","mist":"Провисание поясницы; слишком высокий таз; задержка дыхания; перенос нагрузки только на плечи."},{"code":"CORE_HANGING_KNEE_RAISE","name":"Подъём коленей в висе","type":"compound","track":"reps_only","eq":"bodyweight","pat":"core_hip_flexion","rest":75,"uni":false,"aliases":["Подъём коленей к груди в висе"],"p":["core"],"s":[],"st":["forearms"],"d":"Подъём таза и коленей в висе, нагружающий мышцы живота и сгибатели бедра. Удобен для прогрессии к подъёму прямых ног.","i":"Начни без раскачки, подними колени и в конце слегка подкрути таз вверх. Медленно опусти ноги, сохраняя контроль.","setup":"Хват надёжный; плечи активны; корпус не раскачивается.","mist":"Маятник ногами; движение только бедром без подкручивания таза; быстрый сброс ног; потеря хвата."},{"code":"CORE_AB_WHEEL","name":"Роллаут с колесом для пресса","type":"compound","track":"reps_only","eq":"other","pat":"core_anti_extension","rest":90,"uni":false,"aliases":["Колесо для пресса","Ab wheel"],"p":["core"],"s":["lats"],"st":["glutes"],"d":"Сложное динамическое упражнение на сопротивление разгибанию позвоночника. Хорошо прогрессируется увеличением длины выката.","i":"Сохраняя таз слегка подкрученным, выкатывай колесо вперёд настолько далеко, насколько можешь удержать поясницу, затем вернись за счёт пресса и плечевого пояса.","setup":"Начинай с коленей; поверхность не скользкая; колесо движется прямо.","mist":"Провисание поясницы; слишком дальний выкат; возврат только руками; потеря контроля таза."},{"code":"CORE_DEAD_BUG","name":"Dead bug","type":"isolation","track":"reps_only","eq":"bodyweight","pat":"core_anti_extension","rest":45,"uni":true,"aliases":["Мёртвый жук"],"p":["core"],"s":[],"st":[],"d":"Контрольное упражнение на удержание поясницы и таза при движении рук и ног. Полезно для обучения брейсингу перед более тяжёлыми упражнениями.","i":"Прижми поясницу к полу, медленно разгибай противоположные руку и ногу и возвращай их, не теряя положения таза.","setup":"Бёдра и колени около 90°; руки вверх; дыхание спокойное.","mist":"Поясница отрывается; движение слишком быстрое; чрезмерная амплитуда; напряжение шеи."},{"code":"TRAPS_SHRUG_BB","name":"Шраги со штангой","type":"isolation","track":"weight_reps","eq":"barbell","pat":"shrug","rest":90,"uni":false,"aliases":["Шраги со штангой стоя"],"p":["traps"],"s":[],"st":["forearms"],"d":"Простой тяжёлый вариант подъёма лопаток для верхней трапеции. Легко прогрессируется по нагрузке.","i":"Поднимай плечи вертикально вверх, задержись на мгновение и медленно опускай. Руки остаются прямыми.","setup":"Штанга перед бёдрами; хват удобной ширины; шея нейтральна.","mist":"Круговые движения плечами; сгибание локтей; рывки; запрокидывание головы."},{"code":"BACK_EXTENSION_45","name":"Гиперэкстензия 45° с акцентом на разгибатели спины","type":"compound","track":"weight_reps","eq":"machine","pat":"back_extension","rest":90,"uni":false,"aliases":["Гиперэкстензия на спину"],"p":["erectors"],"s":["glutes","hamstrings"],"st":["core"],"d":"Разгибание корпуса на римском стуле с акцентом на разгибатели позвоночника. Используется как дополнительная работа для задней цепи.","i":"Сохраняй контролируемую нейтральную позицию позвоночника, опускай корпус и поднимайся до линии с ногами без переразгибания.","setup":"Подушка позволяет свободно сгибаться в тазобедренном суставе; стопы надёжно зафиксированы.","mist":"Рывки; переразгибание вверху; чрезмерное округление под нагрузкой; слишком большая амплитуда."},{"code":"FOREARMS_WRIST_CURL","name":"Сгибание кистей с гантелями","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"wrist_flexion","rest":60,"uni":false,"aliases":["Сгибание запястий на предплечья"],"p":["forearms"],"s":[],"st":[],"d":"Изолирующее сгибание запястья для мышц-сгибателей предплечья. Используется как дополнительное упражнение, если хвата и тяг недостаточно.","i":"Зафиксируй предплечья на бедре или скамье и двигай только кистями, медленно опуская вес до растяжения.","setup":"Кисти свободно выходят за край опоры; вес умеренный.","mist":"Движение локтями; рывки; слишком большой вес; чрезмерное разгибание запястья."},{"code":"FOREARMS_REVERSE_WRIST_CURL","name":"Разгибание кистей с гантелями","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"wrist_extension","rest":60,"uni":false,"aliases":["Обратные сгибания кистей"],"p":["forearms"],"s":[],"st":[],"d":"Изолирующее разгибание запястья для мышц-разгибателей предплечья. Полезно как дополнительная работа для баланса мышц предплечья.","i":"Зафиксируй предплечья и поднимай тыльную сторону кисти вверх, затем медленно опускай.","setup":"Предплечья лежат на опоре; ладони направлены вниз; вес небольшой.","mist":"Подъём предплечий; рывки; слишком тяжёлый вес; чрезмерная амплитуда."}]'::jsonb) as x(
    code text,name text,type text,track text,eq text,pat text,rest integer,uni boolean,
    aliases jsonb,p jsonb,s jsonb,st jsonb,d text,i text,setup text,mist text
  )
)
insert into public.exercises(
  code,name,muscle_group,instructions,is_active,created_by,description,equipment_code,
  movement_pattern_code,default_rest_seconds,technique_url,is_unilateral,updated_at,
  mechanics,setup_notes,common_mistakes,exercise_type,tracking_type,aliases
)
select
  code,name,null,i,true,null,d,eq,pat,rest,null,uni,now(),
  case when type in ('compound','isolation') then type else null end,
  setup,mist,type,track,
  coalesce(array(select jsonb_array_elements_text(aliases)),'{}'::text[])
from data
on conflict(code) do update set
  name=excluded.name,
  instructions=excluded.instructions,
  is_active=true,
  description=excluded.description,
  equipment_code=excluded.equipment_code,
  movement_pattern_code=excluded.movement_pattern_code,
  default_rest_seconds=excluded.default_rest_seconds,
  is_unilateral=excluded.is_unilateral,
  updated_at=now(),
  mechanics=excluded.mechanics,
  setup_notes=excluded.setup_notes,
  common_mistakes=excluded.common_mistakes,
  exercise_type=excluded.exercise_type,
  tracking_type=excluded.tracking_type,
  aliases=excluded.aliases;

with data as (
  select *
  from jsonb_to_recordset('[{"code":"CHEST_FLAT_DB_PRESS","name":"Жим гантелей лёжа на горизонтальной скамье","type":"compound","track":"weight_reps","eq":"dumbbell","pat":"horizontal_push","rest":150,"uni":false,"aliases":["Жим гантелей лёжа"],"p":["chest"],"s":["delts_front","triceps"],"st":[],"d":"Базовый жим на грудь со свободной траекторией каждой руки. Позволяет подобрать удобное положение локтей и хорошо подходит для прогрессии нагрузки.","i":"Сведи и опусти лопатки, устойчиво поставь стопы. Опускай гантели к линии середины груди до комфортного растяжения, затем выжимай вверх без удара гантелей друг о друга.","setup":"Скамья горизонтальна; предплечья близки к вертикали в нижней точке; локти не разводи строго в стороны.","mist":"Плечи уходят вперёд; чрезмерно глубокое опускание; отбив; потеря опоры стопами."},{"code":"CHEST_FLAT_BB_PRESS","name":"Жим штанги лёжа","type":"compound","track":"weight_reps","eq":"barbell","pat":"horizontal_push","rest":180,"uni":false,"aliases":["Жим штанги на горизонтальной скамье"],"p":["chest"],"s":["delts_front","triceps"],"st":[],"d":"Классический базовый жим для груди, трицепса и передней дельты. Особенно удобен для точной прогрессии нагрузки.","i":"Сними штангу на прямых руках, опусти к середине или нижней части груди и выжми вверх по устойчивой траектории. Сохраняй лопатки сведёнными и опущенными.","setup":"Хват обычно немного шире плеч; стопы плотно на полу; запястья над локтями.","mist":"Отбив от груди; локти строго в стороны; отрыв таза; потеря напряжения верхней части спины."},{"code":"CHEST_FLAT_SMITH_PRESS","name":"Жим в Смите лёжа","type":"compound","track":"weight_reps","eq":"smith","pat":"horizontal_push","rest":150,"uni":false,"aliases":["Жим в Смите на горизонтальной скамье"],"p":["chest"],"s":["delts_front","triceps"],"st":[],"d":"Горизонтальный жим с фиксированной траекторией. Удобен для стабильной работы близко к отказу без необходимости балансировать штангу.","i":"Расположи скамью так, чтобы гриф опускался к середине груди. Подконтрольно опускай и выжимай, не меняя положения плеч.","setup":"Проверь траекторию пустым грифом; лопатки сведены и опущены; стопы устойчивы.","mist":"Неправильное положение скамьи; плечи уходят вперёд; слишком узкая или широкая постановка рук."},{"code":"CHEST_MACHINE_PRESS","name":"Жим от груди в тренажёре","type":"compound","track":"weight_reps","eq":"machine","pat":"horizontal_push","rest":120,"uni":false,"aliases":["Chest press","Жим на грудь в тренажёре"],"p":["chest"],"s":["delts_front","triceps"],"st":[],"d":"Стабильный жим на грудь в тренажёре. Хорош для набора объёма и работы близко к отказу, когда баланс свободного веса не нужен.","i":"Прижми спину к опоре, держи плечи опущенными. Опускай рукояти до комфортного растяжения груди и выжимай без полного расслабления внизу.","setup":"Настрой сиденье так, чтобы рукояти находились примерно на уровне середины груди.","mist":"Слишком высокая посадка; плечи тянутся к ушам; сокращённая амплитуда; отрыв спины."},{"code":"CHEST_INCLINE_MACHINE_PRESS","name":"Наклонный жим на грудь в тренажёре","type":"compound","track":"weight_reps","eq":"machine","pat":"incline_push","rest":120,"uni":false,"aliases":["Наклонный chest press"],"p":["chest"],"s":["delts_front","triceps"],"st":[],"d":"Стабильный наклонный жим с несколько большим акцентом на ключичную часть большой грудной. Отдельную мышцу «верх груди» для этого создавать не нужно.","i":"Прижми корпус к спинке, опускай рукояти подконтрольно и выжимай вперёд-вверх. Сохраняй плечи опущенными и не укорачивай нижнюю часть амплитуды.","setup":"Высота сиденья должна позволять начать движение без чрезмерного подъёма плеч.","mist":"Слишком вертикальный угол; движение только передней дельтой; отрыв корпуса; короткая амплитуда."},{"code":"CHEST_PUSHUP","name":"Отжимания от пола","type":"compound","track":"bodyweight_reps","eq":"bodyweight","pat":"horizontal_push","rest":90,"uni":false,"aliases":["Отжимания"],"p":["chest"],"s":["delts_front","triceps"],"st":["core"],"d":"Доступный жим собственным весом для груди, трицепса и передней дельты. Нагрузку можно менять темпом, высотой опоры и дополнительным весом.","i":"Держи корпус одной линией, опускай грудь между ладонями и выжимай пол от себя. Лопатки в верхней точке могут естественно двигаться вперёд.","setup":"Ладони немного шире плеч; пальцы вперёд или слегка наружу; корпус напряжён.","mist":"Провисание таза; локти строго в стороны; неполная амплитуда; голова тянется к полу раньше груди."},{"code":"CHEST_CABLE_FLY","name":"Сведение рук в кроссовере","type":"isolation","track":"weight_reps","eq":"cable","pat":"chest_fly","rest":75,"uni":false,"aliases":["Кроссовер на грудь","Сведения на блоках"],"p":["chest"],"s":["delts_front"],"st":[],"d":"Изолирующее приведение плеча с постоянным сопротивлением троса. Удобно для контролируемой работы груди без большого участия трицепса.","i":"Сохраняя небольшой сгиб в локтях, своди руки перед корпусом по дуге и медленно возвращай до комфортного растяжения.","setup":"Стой устойчиво между блоками; плечи опущены; корпус слегка наклонён вперёд.","mist":"Сгибание и разгибание локтей вместо сведения; чрезмерное растяжение плеча; рывки корпусом."},{"code":"CHEST_PEC_DECK","name":"Сведение рук в тренажёре Peck Deck","type":"isolation","track":"weight_reps","eq":"machine","pat":"chest_fly","rest":75,"uni":false,"aliases":["Бабочка на грудь","Pec deck"],"p":["chest"],"s":["delts_front"],"st":[],"d":"Изолирующее упражнение на грудь с фиксированной и легко контролируемой траекторией. Удобно для стабильного объёма и работы близко к отказу.","i":"Сведи рукояти перед собой, не меняя угол в локтях, задержись в сокращении и подконтрольно верни руки назад.","setup":"Настрой сиденье так, чтобы плечевой сустав и рукояти находились на комфортной линии.","mist":"Плечи поднимаются к ушам; чрезмерное растяжение; быстрый возврат веса; движение локтями за счёт трицепса."},{"code":"BACK_LAT_MEDIUM_PRONATED_PULL","name":"Тяга верхнего блока прямым хватом к груди","type":"compound","track":"weight_reps","eq":"cable","pat":"vertical_pull","rest":120,"uni":false,"aliases":["Тяга верхнего блока средним прямым хватом"],"p":["lats"],"s":["back_mid","biceps"],"st":[],"d":"Базовая вертикальная тяга прямым хватом. По назначению близка к другим вариантам хвата, поэтому прежде всего служит альтернативой по удобству.","i":"Подними грудь, опусти плечи и тяни перекладину к верхней части груди, направляя локти вниз. Возвращай вес до контролируемого растяжения.","setup":"Хват примерно 1–1,5 ширины плеч; корпус почти вертикален или слегка отклонён назад.","mist":"Тяга за голову; сильная раскачка; тяга только руками; неполное растяжение."},{"code":"BACK_LAT_SUPINATED_PULL","name":"Тяга верхнего блока обратным хватом","type":"compound","track":"weight_reps","eq":"cable","pat":"vertical_pull","rest":120,"uni":false,"aliases":["Тяга верхнего блока супинированным хватом"],"p":["lats"],"s":["biceps","back_mid"],"st":[],"d":"Вертикальная тяга обратным хватом с заметным участием сгибателей локтя. Полезна как комфортная альтернатива прямому и нейтральному хвату.","i":"Тяни рукоять к верхней части груди, ведя локти вниз и немного назад. Не превращай движение в сильный наклон корпуса.","setup":"Хват около ширины плеч; ладони к себе; запястья держи нейтрально.","mist":"Слишком узкий хват; заламывание запястий; раскачка; сокращённая амплитуда."},{"code":"BACK_LAT_CLOSE_NEUTRAL_PULL","name":"Тяга верхнего блока узким нейтральным хватом","type":"compound","track":"weight_reps","eq":"cable","pat":"vertical_pull","rest":120,"uni":false,"aliases":["Тяга верхнего блока V-рукоятью"],"p":["lats"],"s":["biceps","back_mid"],"st":[],"d":"Комфортная вертикальная тяга с нейтральным положением кистей. Часто позволяет использовать хорошую амплитуду и подходит тем, кому неудобен широкий прямой хват.","i":"Тяни рукоять к верхней части груди, локти направляй вниз вдоль корпуса. В верхней точке дай широчайшим растянуться без потери контроля плеч.","setup":"Корпус почти вертикален; грудь слегка поднята; плечи не тянуть к ушам.","mist":"Сильный наклон назад; тяга только бицепсом; отсутствие растяжения; рывки."},{"code":"BACK_LAT_PRONATED_PULLUP","name":"Подтягивания прямым хватом","type":"compound","track":"bodyweight_reps","eq":"bodyweight","pat":"vertical_pull","rest":180,"uni":false,"aliases":["Подтягивания обычным хватом"],"p":["lats"],"s":["back_mid","biceps"],"st":["core"],"d":"Классическая вертикальная тяга собственным весом. Хорошо развивает широчайшие и общую силу тягового паттерна.","i":"Начни из контролируемого виса, опусти плечи и подтягивай грудь к перекладине, ведя локти вниз. Опускайся без броска.","setup":"Хват немного шире плеч; корпус собран; ноги не используются для раскачки.","mist":"Киппинг; вытягивание шеи; неполное опускание; чрезмерно широкий хват."},{"code":"BACK_LAT_CHINUP","name":"Подтягивания обратным хватом","type":"compound","track":"bodyweight_reps","eq":"bodyweight","pat":"vertical_pull","rest":180,"uni":false,"aliases":["Chin-up","Подтягивания супинированным хватом"],"p":["lats"],"s":["biceps","back_mid"],"st":["core"],"d":"Подтягивание с ладонями к себе. Сохраняет работу широчайших, но обычно сильнее вовлекает бицепс и может быть удобнее некоторым клиентам.","i":"Подтягивай грудь вверх, направляя локти вниз и назад. Полностью контролируй нижнюю часть амплитуды.","setup":"Хват примерно на ширине плеч; запястья нейтральны; без раскачки.","mist":"Рывок ногами; чрезмерное запрокидывание головы; неполный диапазон; боль в кистях из-за неудобной ширины."},{"code":"BACK_MID_BB_ROW","name":"Тяга штанги в наклоне","type":"compound","track":"weight_reps","eq":"barbell","pat":"horizontal_pull","rest":180,"uni":false,"aliases":["Тяга штанги к поясу"],"p":["back_mid"],"s":["lats","biceps"],"st":["core","erectors"],"d":"Базовая горизонтальная тяга со свободным весом. Нагружает середину спины и широчайшие, одновременно требуя удерживать корпус в наклоне.","i":"Зафиксируй наклон корпуса и тяни штангу к нижним рёбрам или верхней части живота. Опускай до полного контроля, не меняя угол корпуса каждым повторением.","setup":"Стопы устойчивы; спина нейтральна; колени слегка согнуты; штанга близко к ногам.","mist":"Раскачка корпусом; округление поясницы; слишком вертикальное положение; подъём плеч."},{"code":"BACK_MID_CHEST_SUPPORTED_DB_ROW","name":"Тяга гантелей с опорой грудью на наклонной скамье","type":"compound","track":"weight_reps","eq":"dumbbell","pat":"horizontal_pull","rest":120,"uni":false,"aliases":["Тяга гантелей лёжа грудью на скамье"],"p":["back_mid"],"s":["lats","biceps","delts_rear"],"st":[],"d":"Горизонтальная тяга с опорой грудью, почти убирающая ограничение со стороны поясницы. Удобна для точной нагрузки на мышцы спины.","i":"Прижми грудь к скамье и тяни гантели назад, сводя лопатки в комфортной амплитуде. Медленно опускай руки до растяжения.","setup":"Скамья примерно 20–45°; шея нейтральна; ноги устойчиво на полу.","mist":"Отрыв груди от скамьи; рывок; подъём плеч к ушам; чрезмерное сгибание кистей."},{"code":"BACK_MID_MACHINE_ROW","name":"Горизонтальная тяга в тренажёре с упором грудью","type":"compound","track":"weight_reps","eq":"machine","pat":"horizontal_pull","rest":120,"uni":false,"aliases":["Тяга сидя в тренажёре на спину"],"p":["back_mid"],"s":["lats","biceps","delts_rear"],"st":[],"d":"Стабильная горизонтальная тяга с минимальной нагрузкой на поясницу. Хороша для безопасной прогрессии и работы близко к отказу.","i":"Сохраняя грудь на упоре, тяни рукояти к корпусу и веди локти назад. Возвращай вес до контролируемого растяжения.","setup":"Настрой сиденье и упор так, чтобы плечи свободно двигались без подъёма к ушам.","mist":"Отрыв груди; короткая амплитуда; рывки; чрезмерное сведение лопаток при потере положения плеча."},{"code":"BACK_LAT_STRAIGHT_ARM_PULLDOWN","name":"Тяга прямыми руками на верхнем блоке","type":"isolation","track":"weight_reps","eq":"cable","pat":"lat_isolation","rest":75,"uni":false,"aliases":["Пуловер на блоке","Straight-arm pulldown"],"p":["lats"],"s":["triceps"],"st":["core"],"d":"Почти односуставное разгибание плеча с акцентом на широчайшие и небольшим вкладом бицепса. Хорошо подходит как дополнительное упражнение после тяг.","i":"Слегка согни локти и веди рукоять дугой от уровня головы к бёдрам, не меняя угол в локте. Медленно вернись до растяжения широчайших.","setup":"Корпус слегка наклонён; рёбра под контролем; трос свободно проходит перед телом.","mist":"Превращение в трицепсовое разгибание; чрезмерный прогиб; раскачка; слишком большой вес."},{"code":"DELTS_PRESS_DB_SEATED","name":"Жим гантелей сидя над головой","type":"compound","track":"weight_reps","eq":"dumbbell","pat":"vertical_push","rest":150,"uni":false,"aliases":["Жим гантелей сидя на плечи"],"p":["delts_front"],"s":["delts_side","triceps"],"st":["core"],"d":"Базовый вертикальный жим для передней дельты и трицепса со свободной траекторией рук. Часто комфортнее штанги для плечевого сустава.","i":"Начни с гантелей около уровня плеч и выжимай вверх, сохраняя рёбра и таз стабильными. Опускай до комфортной глубины.","setup":"Спинка почти вертикальна; стопы устойчивы; кисти можно держать нейтрально или слегка развернуть.","mist":"Сильный прогиб поясницы; слишком глубокое опускание при дискомфорте; удар гантелей наверху; плечи к ушам."},{"code":"DELTS_PRESS_BB","name":"Жим штанги стоя над головой","type":"compound","track":"weight_reps","eq":"barbell","pat":"vertical_push","rest":180,"uni":false,"aliases":["Армейский жим","Overhead press"],"p":["delts_front"],"s":["delts_side","triceps"],"st":["core","glutes"],"d":"Классический вертикальный жим, развивающий плечевой пояс и общую силу верхней части тела. Требует хорошего контроля корпуса.","i":"Выжимай штангу от верхней части груди вверх, слегка убирая голову с траектории, затем возвращай её под гриф. Не компенсируй движение разгибанием поясницы.","setup":"Хват чуть шире плеч; предплечья близки к вертикали; ягодицы и пресс напряжены.","mist":"Сильный прогиб; толчок ногами без задачи делать push press; локти слишком далеко назад; потеря контроля внизу."},{"code":"DELTS_PRESS_MACHINE","name":"Жим вверх в тренажёре","type":"compound","track":"weight_reps","eq":"machine","pat":"vertical_push","rest":120,"uni":false,"aliases":["Жим на плечи в тренажёре"],"p":["delts_front"],"s":["delts_side","triceps"],"st":[],"d":"Стабильный вертикальный жим для плеч и трицепса. Хороший вариант для набора тренировочного объёма без требований к балансу.","i":"Прижми корпус к спинке, выжимай рукояти вверх и подконтрольно опускай до комфортной глубины.","setup":"Настрой сиденье так, чтобы рукояти начинали примерно на уровне плеч или чуть ниже.","mist":"Отрыв поясницы; плечи к ушам; слишком низкая посадка; неполная амплитуда ради веса."},{"code":"DELTS_PRESS_SMITH","name":"Жим в Смите над головой сидя","type":"compound","track":"weight_reps","eq":"smith","pat":"vertical_push","rest":150,"uni":false,"aliases":["Жим на плечи в Смите"],"p":["delts_front"],"s":["delts_side","triceps"],"st":[],"d":"Вертикальный жим по фиксированной траектории. Удобен для стабильной прогрессии и тренировки близко к отказу.","i":"Расположи скамью так, чтобы гриф двигался перед лицом и опускался к уровню подбородка или верхней груди без дискомфорта.","setup":"Спинка почти вертикальна; проверь траекторию пустым грифом; стопы устойчивы.","mist":"Скамья стоит слишком далеко; чрезмерный прогиб; опускание за голову; слишком широкий хват."},{"code":"DELTS_REAR_DB_FLY","name":"Разведение гантелей в наклоне на заднюю дельту","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"rear_delt","rest":75,"uni":false,"aliases":["Махи гантелей в наклоне"],"p":["delts_rear"],"s":["back_mid"],"st":["core"],"d":"Простое упражнение на заднюю дельту со свободным весом. Может выполняться стоя, сидя или с опорой грудью.","i":"Зафиксируй наклон корпуса и разводи руки в стороны по дуге, сохраняя небольшой сгиб локтей. Опускай гантели медленно.","setup":"Корпус наклонён; шея нейтральна; плечи опущены.","mist":"Тяга гантелей локтями назад вместо разведения; раскачка; слишком тяжёлый вес; чрезмерное сведение лопаток."},{"code":"BICEPS_DB_CURL","name":"Сгибание рук с гантелями стоя","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"elbow_flexion","rest":90,"uni":false,"aliases":["Подъём гантелей на бицепс"],"p":["biceps"],"s":["forearms"],"st":["core"],"d":"Базовое сгибание локтя с независимой работой рук. Универсальный вариант для большинства залов.","i":"Сгибай локоть без движения плеча вперёд и медленно опускай гантель до почти полного разгибания. Можно супинировать кисть по мере подъёма.","setup":"Корпус устойчив; локти рядом с туловищем; запястья нейтральны.","mist":"Раскачка; локти уходят вперёд; сокращённая нижняя амплитуда; заламывание кисти."},{"code":"BICEPS_BB_CURL","name":"Сгибание рук со штангой стоя","type":"isolation","track":"weight_reps","eq":"barbell","pat":"elbow_flexion","rest":90,"uni":false,"aliases":["Подъём штанги на бицепс"],"p":["biceps"],"s":["forearms"],"st":["core"],"d":"Классическое двустороннее сгибание на бицепс, удобное для постепенного увеличения веса.","i":"Подними штангу сгибанием локтей, сохраняя плечи относительно неподвижными, затем медленно опусти до контролируемого растяжения.","setup":"Хват примерно на ширине плеч; корпус собран; локти близко к бокам.","mist":"Читинг корпусом; локти сильно вперёд; чрезмерно тяжёлый вес; неполное разгибание."},{"code":"BICEPS_EZ_CURL","name":"Сгибание рук с EZ-грифом стоя","type":"isolation","track":"weight_reps","eq":"barbell","pat":"elbow_flexion","rest":90,"uni":false,"aliases":["Подъём EZ-грифа на бицепс"],"p":["biceps"],"s":["forearms"],"st":["core"],"d":"Вариант подъёма штанги с более нейтральным положением кистей. Часто комфортнее прямого грифа для запястий и локтей.","i":"Сгибай локти без раскачки и контролируемо опускай гриф до почти полного разгибания.","setup":"Выбери удобный изгиб грифа; локти рядом с корпусом.","mist":"Раскачка; чрезмерное сгибание кистей; локти уходят вперёд; слишком быстрый негатив."},{"code":"BICEPS_CABLE_CURL","name":"Сгибание рук на нижнем блоке","type":"isolation","track":"weight_reps","eq":"cable","pat":"elbow_flexion","rest":75,"uni":false,"aliases":["Подъём на бицепс в кроссовере"],"p":["biceps"],"s":["forearms"],"st":[],"d":"Сгибание локтя с постоянным сопротивлением троса. Удобно для ровной техники и точной дозировки нагрузки.","i":"Сохраняй локти неподвижными, сгибай руки до полного контролируемого сокращения и медленно возвращай рукоять.","setup":"Встань достаточно далеко от блока, чтобы трос оставался натянутым внизу.","mist":"Движение плечом; раскачка; потеря натяжения внизу; заламывание запястий."},{"code":"BICEPS_INCLINE_DB_CURL","name":"Сгибание рук с гантелями на наклонной скамье","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"elbow_flexion","rest":90,"uni":false,"aliases":["Наклонные сгибания на бицепс"],"p":["biceps"],"s":["forearms"],"st":[],"d":"Сгибание локтя с плечом отведённым назад и хорошей нагрузкой в растянутом положении. Полезно как один из систематически чередуемых вариантов.","i":"Прижми спину к скамье, не выводи локоть вперёд и сгибай руку без раскачки. Полностью контролируй нижнюю позицию.","setup":"Скамья примерно 45–60°; руки свободно свисают вниз; плечи опущены.","mist":"Локти уходят вперёд; чрезмерное растяжение при дискомфорте; раскачка; быстрый негатив."},{"code":"BICEPS_PREACHER_CURL","name":"Сгибание рук на скамье Скотта","type":"isolation","track":"weight_reps","eq":"barbell","pat":"elbow_flexion","rest":90,"uni":false,"aliases":["Сгибания на скамье Скотта","Preacher curl"],"p":["biceps"],"s":["forearms"],"st":[],"d":"Сгибание локтя с фиксированным плечом, уменьшающее возможность читинга. Хорошо дополняет варианты, где плечо находится позади корпуса.","i":"Держи плечи на подушке, сгибай локти без отрыва рук и медленно разгибай почти до полного диапазона.","setup":"Подмышки близко к верхнему краю подушки; используй EZ-гриф или гантели, если кистям так удобнее.","mist":"Рывок из нижней точки; пассивная блокировка локтя под тяжёлым весом; отрыв плеч от опоры."},{"code":"BICEPS_HAMMER_CURL","name":"Молотковые сгибания с гантелями","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"elbow_flexion","rest":90,"uni":false,"aliases":["Молотки на бицепс"],"p":["biceps"],"s":["forearms"],"st":["core"],"d":"Сгибание локтя нейтральным хватом с большим вкладом плечевой и плечелучевой мышц. Практичный вариант для общей массы сгибателей локтя.","i":"Сохраняй ладони обращёнными друг к другу и сгибай локти без раскачки. Опускай гантели до контролируемого разгибания.","setup":"Локти рядом с корпусом; кисти нейтральны.","mist":"Мах корпусом; подъём плеч; локти уходят вперёд; слишком короткая амплитуда."},{"code":"TRICEPS_STRAIGHT_BAR_PUSHDOWN","name":"Разгибание рук на верхнем блоке с прямой рукоятью","type":"isolation","track":"weight_reps","eq":"cable","pat":"elbow_extension","rest":75,"uni":false,"aliases":["Разгибание на трицепс с прямой рукоятью"],"p":["triceps"],"s":[],"st":[],"d":"Классическое разгибание локтя на блоке с фиксированной рукоятью. Простая альтернатива канату, если так удобнее держать локти и кисти.","i":"Держи локти около корпуса и разгибай руки вниз до контролируемого сокращения, затем медленно вернись.","setup":"Корпус устойчив; плечи опущены; хват комфортной ширины.","mist":"Локти уходят вперёд; движение всем корпусом; чрезмерно тяжёлый вес; заламывание кистей."},{"code":"TRICEPS_SINGLE_ARM_PUSHDOWN","name":"Разгибание одной руки на верхнем блоке","type":"isolation","track":"weight_reps","eq":"cable","pat":"elbow_extension","rest":60,"uni":true,"aliases":["Одноручное разгибание на трицепс"],"p":["triceps"],"s":[],"st":[],"d":"Одностороннее разгибание локтя, позволяющее свободно подобрать положение кисти и сравнивать стороны.","i":"Зафиксируй плечо у корпуса и полностью разгибай локоть без движения плечом. Возвращай вес до комфортного сгибания.","setup":"Можно использовать рукоять или ремень; корпус не поворачивается.","mist":"Ротация корпуса; локоть гуляет; рывок; слишком большой вес."},{"code":"TRICEPS_CLOSE_GRIP_BENCH","name":"Жим штанги лёжа узким хватом","type":"compound","track":"weight_reps","eq":"barbell","pat":"horizontal_push","rest":150,"uni":false,"aliases":["Узкий жим на трицепс"],"p":["triceps"],"s":["chest","delts_front"],"st":[],"d":"Многосуставной жим с повышенным вкладом трицепса. Полезен как тяжёлый вариант, но не является полной биомеханической заменой изолирующим разгибаниям.","i":"Опускай штангу к нижней части груди, удерживая локти ближе к корпусу, и выжимай вверх без отбива.","setup":"Хват примерно на ширине плеч или немного уже; кисти над предплечьями; лопатки стабильны.","mist":"Слишком узкий хват; локти сильно в стороны; отбив; чрезмерная нагрузка на кисти."},{"code":"QUAD_BACK_SQUAT","name":"Приседания со штангой на спине","type":"compound","track":"weight_reps","eq":"barbell","pat":"squat","rest":180,"uni":false,"aliases":["Присед со штангой"],"p":["quads","glutes"],"s":["hamstrings"],"st":["core","erectors"],"d":"Базовое многосуставное упражнение для квадрицепса и ягодиц. Техника сильно зависит от антропометрии, мобильности и удобной стойки.","i":"Сядь вниз между стопами, сохраняя устойчивую опору всей стопой и колени по направлению носков. Поднимайся, одновременно разгибая колени и таз.","setup":"Ширина стоп индивидуальна; штанга стабильно лежит на верхе спины; вдох и брейс перед повтором.","mist":"Колени заваливаются внутрь; потеря опоры пяткой; расслабление корпуса; глубина ниже контролируемой позиции."},{"code":"QUAD_SMITH_SQUAT","name":"Приседания в Смите","type":"compound","track":"weight_reps","eq":"smith","pat":"squat","rest":150,"uni":false,"aliases":["Присед в машине Смита"],"p":["quads","glutes"],"s":["hamstrings"],"st":["core"],"d":"Присед с фиксированной траекторией, позволяющий меньше думать о балансе и легче дозировать нагрузку на ноги.","i":"Расположи стопы так, чтобы в нижней точке сохранялась устойчивость, затем приседай до комфортной глубины и вставай без отрыва стоп.","setup":"Проверь положение стоп пустым грифом; спина нейтральна; колени движутся по линии носков.","mist":"Стопы стоят слишком близко к траектории грифа; колени внутрь; таз подворачивается с потерей контроля."},{"code":"QUAD_LEG_EXTENSION","name":"Разгибание ног в тренажёре","type":"isolation","track":"weight_reps","eq":"machine","pat":"knee_extension","rest":75,"uni":false,"aliases":["Разгибание коленей в тренажёре"],"p":["quads"],"s":[],"st":[],"d":"Изолирующее разгибание колена для квадрицепса. Удобно для прямой нагрузки на квадрицепс без ограничения со стороны спины и ягодиц.","i":"Разгибай колени плавно до почти полного выпрямления и медленно опускай вес, сохраняя таз прижатым.","setup":"Ось колена совпадает с осью тренажёра; валик расположен над нижней частью голени.","mist":"Рывок; отрыв таза; бросание веса вниз; слишком большая нагрузка с потерей контроля."},{"code":"QUAD_REVERSE_LUNGE","name":"Обратные выпады с гантелями","type":"compound","track":"weight_reps","eq":"dumbbell","pat":"lunge","rest":120,"uni":true,"aliases":["Выпады назад"],"p":["quads","glutes"],"s":["hamstrings"],"st":["core"],"d":"Одностороннее упражнение на квадрицепс и ягодицы, обычно легче контролируемое, чем выпады вперёд. Хорошо подходит для сравнения сторон.","i":"Шагни назад, опусти колено к полу и вернись усилием передней ноги. Держи переднюю стопу полностью на полу.","setup":"Ширина шага должна позволять сохранять баланс и колено по линии стопы.","mist":"Отталкивание задней ногой; завал колена внутрь; слишком узкая линия стоп; падение корпуса."},{"code":"QUAD_WALKING_LUNGE","name":"Выпады в движении с гантелями","type":"compound","track":"weight_reps","eq":"dumbbell","pat":"lunge","rest":120,"uni":true,"aliases":["Ходьба выпадами"],"p":["quads","glutes"],"s":["hamstrings"],"st":["core"],"d":"Динамический односторонний вариант для ног и ягодиц, одновременно требующий координации и устойчивости.","i":"Сделай контролируемый шаг, опусти заднее колено и перенеси корпус вперёд в следующий выпад через усилие передней ноги.","setup":"Держи гантели вдоль корпуса; шаги одинаковой длины; сохраняй пространство между стопами по ширине.","mist":"Шаги по одной линии; колено внутрь; толчок задней ногой; слишком быстрый темп."},{"code":"HAMSTRING_RDL_BB","name":"Румынская тяга со штангой","type":"compound","track":"weight_reps","eq":"barbell","pat":"hinge","rest":180,"uni":false,"aliases":["Румынская тяга"],"p":["hamstrings","glutes"],"s":[],"st":["core","erectors"],"d":"Базовый тазовый шарнир для задней поверхности бедра и ягодиц. Хорошо прогрессируется по весу и нагружает мышцы в растянутом положении.","i":"Отводи таз назад при слегка согнутых коленях и веди штангу близко к ногам. Остановись там, где сохраняется нейтральная спина и выраженное растяжение задней поверхности бедра, затем разогни таз.","setup":"Стопы примерно на ширине таза; хват чуть шире ног; корпус собран.","mist":"Присед вместо наклона; штанга далеко от ног; округление спины; попытка обязательно коснуться пола."},{"code":"HAMSTRING_NORDIC_CURL","name":"Нордические сгибания","type":"isolation","track":"bodyweight_reps","eq":"bodyweight","pat":"knee_flexion","rest":120,"uni":false,"aliases":["Nordic curl"],"p":["hamstrings"],"s":[],"st":["core"],"d":"Тяжёлое сгибание колена собственным весом с большой эксцентрической нагрузкой на заднюю поверхность бедра. Подходит, если можно надёжно зафиксировать стопы.","i":"Сохраняя прямую линию от коленей до головы, медленно опускай корпус вперёд, сопротивляясь разгибанию коленей. Помоги руками внизу и вернись настолько активно, насколько позволяет сила.","setup":"Колени на мягкой опоре; пятки надёжно зафиксированы партнёром или оборудованием.","mist":"Сгибание в тазу; слишком быстрое падение; чрезмерный объём для неподготовленного клиента; ненадёжная фиксация стоп."},{"code":"GLUTE_HIP_THRUST_BB","name":"Ягодичный мост со штангой от скамьи","type":"compound","track":"weight_reps","eq":"barbell","pat":"hip_thrust","rest":150,"uni":false,"aliases":["Hip thrust со штангой","Хип-траст"],"p":["glutes"],"s":["hamstrings"],"st":["core"],"d":"Стабильное упражнение для целевой нагрузки большой ягодичной. Хорошо прогрессируется по весу и обычно мало ограничивается спиной.","i":"Опирайся верхом спины на скамью, опусти таз и разогни его до положения, где корпус и бедро образуют линию. Вверху слегка подкрути таз без переразгибания поясницы.","setup":"Гриф лежит на сгибе таза через мягкую накладку; стопы стоят так, чтобы вверху голени были близки к вертикали.","mist":"Переразгибание поясницы; стопы слишком далеко или близко; толчок носками; неполная нижняя амплитуда."},{"code":"GLUTE_HIP_THRUST_SMITH","name":"Ягодичный мост в Смите от скамьи","type":"compound","track":"weight_reps","eq":"smith","pat":"hip_thrust","rest":120,"uni":false,"aliases":["Hip thrust в Смите"],"p":["glutes"],"s":["hamstrings"],"st":["core"],"d":"Стабильный вариант hip thrust с фиксированной траекторией. Удобен для самостоятельной тренировки и работы близко к отказу.","i":"Опусти таз под контролем и разогни до полного сокращения ягодиц без прогиба поясницы. Сохраняй колени по линии стоп.","setup":"Скамья надёжно зафиксирована; гриф с мягкой накладкой; стопы симметричны.","mist":"Скамья скользит; переразгибание поясницы; колени внутрь; движение слишком короткое."},{"code":"GLUTE_CABLE_KICKBACK","name":"Отведение ноги назад на нижнем блоке","type":"isolation","track":"weight_reps","eq":"cable","pat":"hip_extension","rest":60,"uni":true,"aliases":["Кикбэк на ягодицы в кроссовере"],"p":["glutes"],"s":["hamstrings"],"st":["core"],"d":"Одностороннее разгибание бедра с постоянным сопротивлением троса. Подходит для дополнительной нагрузки ягодиц без тяжёлой осевой нагрузки.","i":"Сохраняя таз направленным вперёд, отводи бедро назад до сокращения ягодицы и медленно возвращай ногу.","setup":"Манжета на голени или лодыжке; корпус стабилен; опорная нога слегка согнута.","mist":"Прогиб поясницы; разворот таза; мах ногой; слишком большая амплитуда."},{"code":"GLUTE_BACK_EXTENSION_45","name":"Гиперэкстензия 45° с акцентом на ягодицы","type":"compound","track":"weight_reps","eq":"machine","pat":"hip_extension","rest":90,"uni":false,"aliases":["Гиперэкстензия на ягодицы"],"p":["glutes"],"s":["hamstrings"],"st":["erectors"],"d":"Разгибание таза на римском стуле с акцентом на ягодицы и заднюю поверхность бедра. Удобный дополнительный вариант без тяжёлой штанги.","i":"Отводи таз назад и опускай корпус за счёт тазобедренного сустава. Поднимайся сокращением ягодиц до нейтрального положения корпуса.","setup":"Край подушки находится ниже сгиба таза; стопы надёжно зафиксированы.","mist":"Переразгибание поясницы; движение позвоночником вместо таза; слишком высокая подушка; рывки."},{"code":"GLUTE_MACHINE_ABDUCTION","name":"Отведение бёдер в тренажёре","type":"isolation","track":"weight_reps","eq":"machine","pat":"hip_abduction","rest":60,"uni":false,"aliases":["Разведение ног в тренажёре"],"p":["glutes_medius"],"s":["glutes"],"st":[],"d":"Изолированное отведение бедра для средней ягодичной и других отводящих мышц. Не является обязательным для каждой программы, но удобно как дополнительная работа.","i":"Разводи бёдра плавно до комфортной амплитуды и медленно возвращай, сохраняя таз устойчивым.","setup":"Сядь устойчиво; настрой упоры так, чтобы движение начиналось без болезненного растяжения.","mist":"Рывки; чрезмерный наклон корпуса ради веса; быстрое схлопывание ног; слишком большая амплитуда."},{"code":"LEGS_MACHINE_ADDUCTION","name":"Приведение бёдер в тренажёре","type":"isolation","track":"weight_reps","eq":"machine","pat":"hip_adduction","rest":60,"uni":false,"aliases":["Сведение ног в тренажёре"],"p":["adductors"],"s":[],"st":[],"d":"Изолированное приведение бедра для приводящих мышц. Полезно как дополнительное упражнение, если в программе нужен прямой объём на внутреннюю поверхность бедра.","i":"Своди бёдра плавно до комфортного сокращения и медленно возвращай их наружу без рывка.","setup":"Настрой стартовую ширину так, чтобы не было болезненного растяжения в паху.","mist":"Резкое растяжение; бросание веса; чрезмерная стартовая ширина; отрыв таза от сиденья."},{"code":"CALVES_SINGLE_LEG_DB","name":"Подъём на носок одной ногой с гантелью","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"calf_raise","rest":60,"uni":true,"aliases":["Одноногий подъём на носок"],"p":["calves"],"s":[],"st":[],"d":"Доступный вариант тренировки икр с почти прямым коленом, не требующий специального тренажёра. Позволяет отдельно сравнивать силу сторон.","i":"Опускай пятку до комфортного растяжения и поднимайся максимально высоко на носок без пружинящих движений.","setup":"Передняя часть стопы на устойчивой платформе; свободной рукой можно держаться за опору.","mist":"Пружинящий темп; сгибание колена; разворот стопы; сокращённая амплитуда."},{"code":"CORE_PLANK","name":"Планка на предплечьях","type":"isolation","track":"duration","eq":"bodyweight","pat":"core_anti_extension","rest":60,"uni":false,"aliases":["Планка"],"p":["core"],"s":[],"st":["glutes"],"d":"Изометрическое упражнение на сопротивление разгибанию поясницы. Подходит для базового контроля корпуса и не требует оборудования.","i":"Сожми ягодицы, слегка подкрути таз и удерживай рёбра над тазом. Дыши, не теряя положения корпуса.","setup":"Локти под плечами; ноги прямые; тело образует ровную линию.","mist":"Провисание поясницы; слишком высокий таз; задержка дыхания; перенос нагрузки только на плечи."},{"code":"CORE_HANGING_KNEE_RAISE","name":"Подъём коленей в висе","type":"compound","track":"reps_only","eq":"bodyweight","pat":"core_hip_flexion","rest":75,"uni":false,"aliases":["Подъём коленей к груди в висе"],"p":["core"],"s":[],"st":["forearms"],"d":"Подъём таза и коленей в висе, нагружающий мышцы живота и сгибатели бедра. Удобен для прогрессии к подъёму прямых ног.","i":"Начни без раскачки, подними колени и в конце слегка подкрути таз вверх. Медленно опусти ноги, сохраняя контроль.","setup":"Хват надёжный; плечи активны; корпус не раскачивается.","mist":"Маятник ногами; движение только бедром без подкручивания таза; быстрый сброс ног; потеря хвата."},{"code":"CORE_AB_WHEEL","name":"Роллаут с колесом для пресса","type":"compound","track":"reps_only","eq":"other","pat":"core_anti_extension","rest":90,"uni":false,"aliases":["Колесо для пресса","Ab wheel"],"p":["core"],"s":["lats"],"st":["glutes"],"d":"Сложное динамическое упражнение на сопротивление разгибанию позвоночника. Хорошо прогрессируется увеличением длины выката.","i":"Сохраняя таз слегка подкрученным, выкатывай колесо вперёд настолько далеко, насколько можешь удержать поясницу, затем вернись за счёт пресса и плечевого пояса.","setup":"Начинай с коленей; поверхность не скользкая; колесо движется прямо.","mist":"Провисание поясницы; слишком дальний выкат; возврат только руками; потеря контроля таза."},{"code":"CORE_DEAD_BUG","name":"Dead bug","type":"isolation","track":"reps_only","eq":"bodyweight","pat":"core_anti_extension","rest":45,"uni":true,"aliases":["Мёртвый жук"],"p":["core"],"s":[],"st":[],"d":"Контрольное упражнение на удержание поясницы и таза при движении рук и ног. Полезно для обучения брейсингу перед более тяжёлыми упражнениями.","i":"Прижми поясницу к полу, медленно разгибай противоположные руку и ногу и возвращай их, не теряя положения таза.","setup":"Бёдра и колени около 90°; руки вверх; дыхание спокойное.","mist":"Поясница отрывается; движение слишком быстрое; чрезмерная амплитуда; напряжение шеи."},{"code":"TRAPS_SHRUG_BB","name":"Шраги со штангой","type":"isolation","track":"weight_reps","eq":"barbell","pat":"shrug","rest":90,"uni":false,"aliases":["Шраги со штангой стоя"],"p":["traps"],"s":[],"st":["forearms"],"d":"Простой тяжёлый вариант подъёма лопаток для верхней трапеции. Легко прогрессируется по нагрузке.","i":"Поднимай плечи вертикально вверх, задержись на мгновение и медленно опускай. Руки остаются прямыми.","setup":"Штанга перед бёдрами; хват удобной ширины; шея нейтральна.","mist":"Круговые движения плечами; сгибание локтей; рывки; запрокидывание головы."},{"code":"BACK_EXTENSION_45","name":"Гиперэкстензия 45° с акцентом на разгибатели спины","type":"compound","track":"weight_reps","eq":"machine","pat":"back_extension","rest":90,"uni":false,"aliases":["Гиперэкстензия на спину"],"p":["erectors"],"s":["glutes","hamstrings"],"st":["core"],"d":"Разгибание корпуса на римском стуле с акцентом на разгибатели позвоночника. Используется как дополнительная работа для задней цепи.","i":"Сохраняй контролируемую нейтральную позицию позвоночника, опускай корпус и поднимайся до линии с ногами без переразгибания.","setup":"Подушка позволяет свободно сгибаться в тазобедренном суставе; стопы надёжно зафиксированы.","mist":"Рывки; переразгибание вверху; чрезмерное округление под нагрузкой; слишком большая амплитуда."},{"code":"FOREARMS_WRIST_CURL","name":"Сгибание кистей с гантелями","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"wrist_flexion","rest":60,"uni":false,"aliases":["Сгибание запястий на предплечья"],"p":["forearms"],"s":[],"st":[],"d":"Изолирующее сгибание запястья для мышц-сгибателей предплечья. Используется как дополнительное упражнение, если хвата и тяг недостаточно.","i":"Зафиксируй предплечья на бедре или скамье и двигай только кистями, медленно опуская вес до растяжения.","setup":"Кисти свободно выходят за край опоры; вес умеренный.","mist":"Движение локтями; рывки; слишком большой вес; чрезмерное разгибание запястья."},{"code":"FOREARMS_REVERSE_WRIST_CURL","name":"Разгибание кистей с гантелями","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"wrist_extension","rest":60,"uni":false,"aliases":["Обратные сгибания кистей"],"p":["forearms"],"s":[],"st":[],"d":"Изолирующее разгибание запястья для мышц-разгибателей предплечья. Полезно как дополнительная работа для баланса мышц предплечья.","i":"Зафиксируй предплечья и поднимай тыльную сторону кисти вверх, затем медленно опускай.","setup":"Предплечья лежат на опоре; ладони направлены вниз; вес небольшой.","mist":"Подъём предплечий; рывки; слишком тяжёлый вес; чрезмерная амплитуда."}]'::jsonb) as x(code text,p jsonb,s jsonb,st jsonb)
), ids as (
  select e.id,d.* from data d join public.exercises e using(code)
)
delete from public.exercise_muscle_groups emg
using ids
where emg.exercise_id=ids.id;

with data as (
  select *
  from jsonb_to_recordset('[{"code":"CHEST_FLAT_DB_PRESS","name":"Жим гантелей лёжа на горизонтальной скамье","type":"compound","track":"weight_reps","eq":"dumbbell","pat":"horizontal_push","rest":150,"uni":false,"aliases":["Жим гантелей лёжа"],"p":["chest"],"s":["delts_front","triceps"],"st":[],"d":"Базовый жим на грудь со свободной траекторией каждой руки. Позволяет подобрать удобное положение локтей и хорошо подходит для прогрессии нагрузки.","i":"Сведи и опусти лопатки, устойчиво поставь стопы. Опускай гантели к линии середины груди до комфортного растяжения, затем выжимай вверх без удара гантелей друг о друга.","setup":"Скамья горизонтальна; предплечья близки к вертикали в нижней точке; локти не разводи строго в стороны.","mist":"Плечи уходят вперёд; чрезмерно глубокое опускание; отбив; потеря опоры стопами."},{"code":"CHEST_FLAT_BB_PRESS","name":"Жим штанги лёжа","type":"compound","track":"weight_reps","eq":"barbell","pat":"horizontal_push","rest":180,"uni":false,"aliases":["Жим штанги на горизонтальной скамье"],"p":["chest"],"s":["delts_front","triceps"],"st":[],"d":"Классический базовый жим для груди, трицепса и передней дельты. Особенно удобен для точной прогрессии нагрузки.","i":"Сними штангу на прямых руках, опусти к середине или нижней части груди и выжми вверх по устойчивой траектории. Сохраняй лопатки сведёнными и опущенными.","setup":"Хват обычно немного шире плеч; стопы плотно на полу; запястья над локтями.","mist":"Отбив от груди; локти строго в стороны; отрыв таза; потеря напряжения верхней части спины."},{"code":"CHEST_FLAT_SMITH_PRESS","name":"Жим в Смите лёжа","type":"compound","track":"weight_reps","eq":"smith","pat":"horizontal_push","rest":150,"uni":false,"aliases":["Жим в Смите на горизонтальной скамье"],"p":["chest"],"s":["delts_front","triceps"],"st":[],"d":"Горизонтальный жим с фиксированной траекторией. Удобен для стабильной работы близко к отказу без необходимости балансировать штангу.","i":"Расположи скамью так, чтобы гриф опускался к середине груди. Подконтрольно опускай и выжимай, не меняя положения плеч.","setup":"Проверь траекторию пустым грифом; лопатки сведены и опущены; стопы устойчивы.","mist":"Неправильное положение скамьи; плечи уходят вперёд; слишком узкая или широкая постановка рук."},{"code":"CHEST_MACHINE_PRESS","name":"Жим от груди в тренажёре","type":"compound","track":"weight_reps","eq":"machine","pat":"horizontal_push","rest":120,"uni":false,"aliases":["Chest press","Жим на грудь в тренажёре"],"p":["chest"],"s":["delts_front","triceps"],"st":[],"d":"Стабильный жим на грудь в тренажёре. Хорош для набора объёма и работы близко к отказу, когда баланс свободного веса не нужен.","i":"Прижми спину к опоре, держи плечи опущенными. Опускай рукояти до комфортного растяжения груди и выжимай без полного расслабления внизу.","setup":"Настрой сиденье так, чтобы рукояти находились примерно на уровне середины груди.","mist":"Слишком высокая посадка; плечи тянутся к ушам; сокращённая амплитуда; отрыв спины."},{"code":"CHEST_INCLINE_MACHINE_PRESS","name":"Наклонный жим на грудь в тренажёре","type":"compound","track":"weight_reps","eq":"machine","pat":"incline_push","rest":120,"uni":false,"aliases":["Наклонный chest press"],"p":["chest"],"s":["delts_front","triceps"],"st":[],"d":"Стабильный наклонный жим с несколько большим акцентом на ключичную часть большой грудной. Отдельную мышцу «верх груди» для этого создавать не нужно.","i":"Прижми корпус к спинке, опускай рукояти подконтрольно и выжимай вперёд-вверх. Сохраняй плечи опущенными и не укорачивай нижнюю часть амплитуды.","setup":"Высота сиденья должна позволять начать движение без чрезмерного подъёма плеч.","mist":"Слишком вертикальный угол; движение только передней дельтой; отрыв корпуса; короткая амплитуда."},{"code":"CHEST_PUSHUP","name":"Отжимания от пола","type":"compound","track":"bodyweight_reps","eq":"bodyweight","pat":"horizontal_push","rest":90,"uni":false,"aliases":["Отжимания"],"p":["chest"],"s":["delts_front","triceps"],"st":["core"],"d":"Доступный жим собственным весом для груди, трицепса и передней дельты. Нагрузку можно менять темпом, высотой опоры и дополнительным весом.","i":"Держи корпус одной линией, опускай грудь между ладонями и выжимай пол от себя. Лопатки в верхней точке могут естественно двигаться вперёд.","setup":"Ладони немного шире плеч; пальцы вперёд или слегка наружу; корпус напряжён.","mist":"Провисание таза; локти строго в стороны; неполная амплитуда; голова тянется к полу раньше груди."},{"code":"CHEST_CABLE_FLY","name":"Сведение рук в кроссовере","type":"isolation","track":"weight_reps","eq":"cable","pat":"chest_fly","rest":75,"uni":false,"aliases":["Кроссовер на грудь","Сведения на блоках"],"p":["chest"],"s":["delts_front"],"st":[],"d":"Изолирующее приведение плеча с постоянным сопротивлением троса. Удобно для контролируемой работы груди без большого участия трицепса.","i":"Сохраняя небольшой сгиб в локтях, своди руки перед корпусом по дуге и медленно возвращай до комфортного растяжения.","setup":"Стой устойчиво между блоками; плечи опущены; корпус слегка наклонён вперёд.","mist":"Сгибание и разгибание локтей вместо сведения; чрезмерное растяжение плеча; рывки корпусом."},{"code":"CHEST_PEC_DECK","name":"Сведение рук в тренажёре Peck Deck","type":"isolation","track":"weight_reps","eq":"machine","pat":"chest_fly","rest":75,"uni":false,"aliases":["Бабочка на грудь","Pec deck"],"p":["chest"],"s":["delts_front"],"st":[],"d":"Изолирующее упражнение на грудь с фиксированной и легко контролируемой траекторией. Удобно для стабильного объёма и работы близко к отказу.","i":"Сведи рукояти перед собой, не меняя угол в локтях, задержись в сокращении и подконтрольно верни руки назад.","setup":"Настрой сиденье так, чтобы плечевой сустав и рукояти находились на комфортной линии.","mist":"Плечи поднимаются к ушам; чрезмерное растяжение; быстрый возврат веса; движение локтями за счёт трицепса."},{"code":"BACK_LAT_MEDIUM_PRONATED_PULL","name":"Тяга верхнего блока прямым хватом к груди","type":"compound","track":"weight_reps","eq":"cable","pat":"vertical_pull","rest":120,"uni":false,"aliases":["Тяга верхнего блока средним прямым хватом"],"p":["lats"],"s":["back_mid","biceps"],"st":[],"d":"Базовая вертикальная тяга прямым хватом. По назначению близка к другим вариантам хвата, поэтому прежде всего служит альтернативой по удобству.","i":"Подними грудь, опусти плечи и тяни перекладину к верхней части груди, направляя локти вниз. Возвращай вес до контролируемого растяжения.","setup":"Хват примерно 1–1,5 ширины плеч; корпус почти вертикален или слегка отклонён назад.","mist":"Тяга за голову; сильная раскачка; тяга только руками; неполное растяжение."},{"code":"BACK_LAT_SUPINATED_PULL","name":"Тяга верхнего блока обратным хватом","type":"compound","track":"weight_reps","eq":"cable","pat":"vertical_pull","rest":120,"uni":false,"aliases":["Тяга верхнего блока супинированным хватом"],"p":["lats"],"s":["biceps","back_mid"],"st":[],"d":"Вертикальная тяга обратным хватом с заметным участием сгибателей локтя. Полезна как комфортная альтернатива прямому и нейтральному хвату.","i":"Тяни рукоять к верхней части груди, ведя локти вниз и немного назад. Не превращай движение в сильный наклон корпуса.","setup":"Хват около ширины плеч; ладони к себе; запястья держи нейтрально.","mist":"Слишком узкий хват; заламывание запястий; раскачка; сокращённая амплитуда."},{"code":"BACK_LAT_CLOSE_NEUTRAL_PULL","name":"Тяга верхнего блока узким нейтральным хватом","type":"compound","track":"weight_reps","eq":"cable","pat":"vertical_pull","rest":120,"uni":false,"aliases":["Тяга верхнего блока V-рукоятью"],"p":["lats"],"s":["biceps","back_mid"],"st":[],"d":"Комфортная вертикальная тяга с нейтральным положением кистей. Часто позволяет использовать хорошую амплитуду и подходит тем, кому неудобен широкий прямой хват.","i":"Тяни рукоять к верхней части груди, локти направляй вниз вдоль корпуса. В верхней точке дай широчайшим растянуться без потери контроля плеч.","setup":"Корпус почти вертикален; грудь слегка поднята; плечи не тянуть к ушам.","mist":"Сильный наклон назад; тяга только бицепсом; отсутствие растяжения; рывки."},{"code":"BACK_LAT_PRONATED_PULLUP","name":"Подтягивания прямым хватом","type":"compound","track":"bodyweight_reps","eq":"bodyweight","pat":"vertical_pull","rest":180,"uni":false,"aliases":["Подтягивания обычным хватом"],"p":["lats"],"s":["back_mid","biceps"],"st":["core"],"d":"Классическая вертикальная тяга собственным весом. Хорошо развивает широчайшие и общую силу тягового паттерна.","i":"Начни из контролируемого виса, опусти плечи и подтягивай грудь к перекладине, ведя локти вниз. Опускайся без броска.","setup":"Хват немного шире плеч; корпус собран; ноги не используются для раскачки.","mist":"Киппинг; вытягивание шеи; неполное опускание; чрезмерно широкий хват."},{"code":"BACK_LAT_CHINUP","name":"Подтягивания обратным хватом","type":"compound","track":"bodyweight_reps","eq":"bodyweight","pat":"vertical_pull","rest":180,"uni":false,"aliases":["Chin-up","Подтягивания супинированным хватом"],"p":["lats"],"s":["biceps","back_mid"],"st":["core"],"d":"Подтягивание с ладонями к себе. Сохраняет работу широчайших, но обычно сильнее вовлекает бицепс и может быть удобнее некоторым клиентам.","i":"Подтягивай грудь вверх, направляя локти вниз и назад. Полностью контролируй нижнюю часть амплитуды.","setup":"Хват примерно на ширине плеч; запястья нейтральны; без раскачки.","mist":"Рывок ногами; чрезмерное запрокидывание головы; неполный диапазон; боль в кистях из-за неудобной ширины."},{"code":"BACK_MID_BB_ROW","name":"Тяга штанги в наклоне","type":"compound","track":"weight_reps","eq":"barbell","pat":"horizontal_pull","rest":180,"uni":false,"aliases":["Тяга штанги к поясу"],"p":["back_mid"],"s":["lats","biceps"],"st":["core","erectors"],"d":"Базовая горизонтальная тяга со свободным весом. Нагружает середину спины и широчайшие, одновременно требуя удерживать корпус в наклоне.","i":"Зафиксируй наклон корпуса и тяни штангу к нижним рёбрам или верхней части живота. Опускай до полного контроля, не меняя угол корпуса каждым повторением.","setup":"Стопы устойчивы; спина нейтральна; колени слегка согнуты; штанга близко к ногам.","mist":"Раскачка корпусом; округление поясницы; слишком вертикальное положение; подъём плеч."},{"code":"BACK_MID_CHEST_SUPPORTED_DB_ROW","name":"Тяга гантелей с опорой грудью на наклонной скамье","type":"compound","track":"weight_reps","eq":"dumbbell","pat":"horizontal_pull","rest":120,"uni":false,"aliases":["Тяга гантелей лёжа грудью на скамье"],"p":["back_mid"],"s":["lats","biceps","delts_rear"],"st":[],"d":"Горизонтальная тяга с опорой грудью, почти убирающая ограничение со стороны поясницы. Удобна для точной нагрузки на мышцы спины.","i":"Прижми грудь к скамье и тяни гантели назад, сводя лопатки в комфортной амплитуде. Медленно опускай руки до растяжения.","setup":"Скамья примерно 20–45°; шея нейтральна; ноги устойчиво на полу.","mist":"Отрыв груди от скамьи; рывок; подъём плеч к ушам; чрезмерное сгибание кистей."},{"code":"BACK_MID_MACHINE_ROW","name":"Горизонтальная тяга в тренажёре с упором грудью","type":"compound","track":"weight_reps","eq":"machine","pat":"horizontal_pull","rest":120,"uni":false,"aliases":["Тяга сидя в тренажёре на спину"],"p":["back_mid"],"s":["lats","biceps","delts_rear"],"st":[],"d":"Стабильная горизонтальная тяга с минимальной нагрузкой на поясницу. Хороша для безопасной прогрессии и работы близко к отказу.","i":"Сохраняя грудь на упоре, тяни рукояти к корпусу и веди локти назад. Возвращай вес до контролируемого растяжения.","setup":"Настрой сиденье и упор так, чтобы плечи свободно двигались без подъёма к ушам.","mist":"Отрыв груди; короткая амплитуда; рывки; чрезмерное сведение лопаток при потере положения плеча."},{"code":"BACK_LAT_STRAIGHT_ARM_PULLDOWN","name":"Тяга прямыми руками на верхнем блоке","type":"isolation","track":"weight_reps","eq":"cable","pat":"lat_isolation","rest":75,"uni":false,"aliases":["Пуловер на блоке","Straight-arm pulldown"],"p":["lats"],"s":["triceps"],"st":["core"],"d":"Почти односуставное разгибание плеча с акцентом на широчайшие и небольшим вкладом бицепса. Хорошо подходит как дополнительное упражнение после тяг.","i":"Слегка согни локти и веди рукоять дугой от уровня головы к бёдрам, не меняя угол в локте. Медленно вернись до растяжения широчайших.","setup":"Корпус слегка наклонён; рёбра под контролем; трос свободно проходит перед телом.","mist":"Превращение в трицепсовое разгибание; чрезмерный прогиб; раскачка; слишком большой вес."},{"code":"DELTS_PRESS_DB_SEATED","name":"Жим гантелей сидя над головой","type":"compound","track":"weight_reps","eq":"dumbbell","pat":"vertical_push","rest":150,"uni":false,"aliases":["Жим гантелей сидя на плечи"],"p":["delts_front"],"s":["delts_side","triceps"],"st":["core"],"d":"Базовый вертикальный жим для передней дельты и трицепса со свободной траекторией рук. Часто комфортнее штанги для плечевого сустава.","i":"Начни с гантелей около уровня плеч и выжимай вверх, сохраняя рёбра и таз стабильными. Опускай до комфортной глубины.","setup":"Спинка почти вертикальна; стопы устойчивы; кисти можно держать нейтрально или слегка развернуть.","mist":"Сильный прогиб поясницы; слишком глубокое опускание при дискомфорте; удар гантелей наверху; плечи к ушам."},{"code":"DELTS_PRESS_BB","name":"Жим штанги стоя над головой","type":"compound","track":"weight_reps","eq":"barbell","pat":"vertical_push","rest":180,"uni":false,"aliases":["Армейский жим","Overhead press"],"p":["delts_front"],"s":["delts_side","triceps"],"st":["core","glutes"],"d":"Классический вертикальный жим, развивающий плечевой пояс и общую силу верхней части тела. Требует хорошего контроля корпуса.","i":"Выжимай штангу от верхней части груди вверх, слегка убирая голову с траектории, затем возвращай её под гриф. Не компенсируй движение разгибанием поясницы.","setup":"Хват чуть шире плеч; предплечья близки к вертикали; ягодицы и пресс напряжены.","mist":"Сильный прогиб; толчок ногами без задачи делать push press; локти слишком далеко назад; потеря контроля внизу."},{"code":"DELTS_PRESS_MACHINE","name":"Жим вверх в тренажёре","type":"compound","track":"weight_reps","eq":"machine","pat":"vertical_push","rest":120,"uni":false,"aliases":["Жим на плечи в тренажёре"],"p":["delts_front"],"s":["delts_side","triceps"],"st":[],"d":"Стабильный вертикальный жим для плеч и трицепса. Хороший вариант для набора тренировочного объёма без требований к балансу.","i":"Прижми корпус к спинке, выжимай рукояти вверх и подконтрольно опускай до комфортной глубины.","setup":"Настрой сиденье так, чтобы рукояти начинали примерно на уровне плеч или чуть ниже.","mist":"Отрыв поясницы; плечи к ушам; слишком низкая посадка; неполная амплитуда ради веса."},{"code":"DELTS_PRESS_SMITH","name":"Жим в Смите над головой сидя","type":"compound","track":"weight_reps","eq":"smith","pat":"vertical_push","rest":150,"uni":false,"aliases":["Жим на плечи в Смите"],"p":["delts_front"],"s":["delts_side","triceps"],"st":[],"d":"Вертикальный жим по фиксированной траектории. Удобен для стабильной прогрессии и тренировки близко к отказу.","i":"Расположи скамью так, чтобы гриф двигался перед лицом и опускался к уровню подбородка или верхней груди без дискомфорта.","setup":"Спинка почти вертикальна; проверь траекторию пустым грифом; стопы устойчивы.","mist":"Скамья стоит слишком далеко; чрезмерный прогиб; опускание за голову; слишком широкий хват."},{"code":"DELTS_REAR_DB_FLY","name":"Разведение гантелей в наклоне на заднюю дельту","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"rear_delt","rest":75,"uni":false,"aliases":["Махи гантелей в наклоне"],"p":["delts_rear"],"s":["back_mid"],"st":["core"],"d":"Простое упражнение на заднюю дельту со свободным весом. Может выполняться стоя, сидя или с опорой грудью.","i":"Зафиксируй наклон корпуса и разводи руки в стороны по дуге, сохраняя небольшой сгиб локтей. Опускай гантели медленно.","setup":"Корпус наклонён; шея нейтральна; плечи опущены.","mist":"Тяга гантелей локтями назад вместо разведения; раскачка; слишком тяжёлый вес; чрезмерное сведение лопаток."},{"code":"BICEPS_DB_CURL","name":"Сгибание рук с гантелями стоя","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"elbow_flexion","rest":90,"uni":false,"aliases":["Подъём гантелей на бицепс"],"p":["biceps"],"s":["forearms"],"st":["core"],"d":"Базовое сгибание локтя с независимой работой рук. Универсальный вариант для большинства залов.","i":"Сгибай локоть без движения плеча вперёд и медленно опускай гантель до почти полного разгибания. Можно супинировать кисть по мере подъёма.","setup":"Корпус устойчив; локти рядом с туловищем; запястья нейтральны.","mist":"Раскачка; локти уходят вперёд; сокращённая нижняя амплитуда; заламывание кисти."},{"code":"BICEPS_BB_CURL","name":"Сгибание рук со штангой стоя","type":"isolation","track":"weight_reps","eq":"barbell","pat":"elbow_flexion","rest":90,"uni":false,"aliases":["Подъём штанги на бицепс"],"p":["biceps"],"s":["forearms"],"st":["core"],"d":"Классическое двустороннее сгибание на бицепс, удобное для постепенного увеличения веса.","i":"Подними штангу сгибанием локтей, сохраняя плечи относительно неподвижными, затем медленно опусти до контролируемого растяжения.","setup":"Хват примерно на ширине плеч; корпус собран; локти близко к бокам.","mist":"Читинг корпусом; локти сильно вперёд; чрезмерно тяжёлый вес; неполное разгибание."},{"code":"BICEPS_EZ_CURL","name":"Сгибание рук с EZ-грифом стоя","type":"isolation","track":"weight_reps","eq":"barbell","pat":"elbow_flexion","rest":90,"uni":false,"aliases":["Подъём EZ-грифа на бицепс"],"p":["biceps"],"s":["forearms"],"st":["core"],"d":"Вариант подъёма штанги с более нейтральным положением кистей. Часто комфортнее прямого грифа для запястий и локтей.","i":"Сгибай локти без раскачки и контролируемо опускай гриф до почти полного разгибания.","setup":"Выбери удобный изгиб грифа; локти рядом с корпусом.","mist":"Раскачка; чрезмерное сгибание кистей; локти уходят вперёд; слишком быстрый негатив."},{"code":"BICEPS_CABLE_CURL","name":"Сгибание рук на нижнем блоке","type":"isolation","track":"weight_reps","eq":"cable","pat":"elbow_flexion","rest":75,"uni":false,"aliases":["Подъём на бицепс в кроссовере"],"p":["biceps"],"s":["forearms"],"st":[],"d":"Сгибание локтя с постоянным сопротивлением троса. Удобно для ровной техники и точной дозировки нагрузки.","i":"Сохраняй локти неподвижными, сгибай руки до полного контролируемого сокращения и медленно возвращай рукоять.","setup":"Встань достаточно далеко от блока, чтобы трос оставался натянутым внизу.","mist":"Движение плечом; раскачка; потеря натяжения внизу; заламывание запястий."},{"code":"BICEPS_INCLINE_DB_CURL","name":"Сгибание рук с гантелями на наклонной скамье","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"elbow_flexion","rest":90,"uni":false,"aliases":["Наклонные сгибания на бицепс"],"p":["biceps"],"s":["forearms"],"st":[],"d":"Сгибание локтя с плечом отведённым назад и хорошей нагрузкой в растянутом положении. Полезно как один из систематически чередуемых вариантов.","i":"Прижми спину к скамье, не выводи локоть вперёд и сгибай руку без раскачки. Полностью контролируй нижнюю позицию.","setup":"Скамья примерно 45–60°; руки свободно свисают вниз; плечи опущены.","mist":"Локти уходят вперёд; чрезмерное растяжение при дискомфорте; раскачка; быстрый негатив."},{"code":"BICEPS_PREACHER_CURL","name":"Сгибание рук на скамье Скотта","type":"isolation","track":"weight_reps","eq":"barbell","pat":"elbow_flexion","rest":90,"uni":false,"aliases":["Сгибания на скамье Скотта","Preacher curl"],"p":["biceps"],"s":["forearms"],"st":[],"d":"Сгибание локтя с фиксированным плечом, уменьшающее возможность читинга. Хорошо дополняет варианты, где плечо находится позади корпуса.","i":"Держи плечи на подушке, сгибай локти без отрыва рук и медленно разгибай почти до полного диапазона.","setup":"Подмышки близко к верхнему краю подушки; используй EZ-гриф или гантели, если кистям так удобнее.","mist":"Рывок из нижней точки; пассивная блокировка локтя под тяжёлым весом; отрыв плеч от опоры."},{"code":"BICEPS_HAMMER_CURL","name":"Молотковые сгибания с гантелями","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"elbow_flexion","rest":90,"uni":false,"aliases":["Молотки на бицепс"],"p":["biceps"],"s":["forearms"],"st":["core"],"d":"Сгибание локтя нейтральным хватом с большим вкладом плечевой и плечелучевой мышц. Практичный вариант для общей массы сгибателей локтя.","i":"Сохраняй ладони обращёнными друг к другу и сгибай локти без раскачки. Опускай гантели до контролируемого разгибания.","setup":"Локти рядом с корпусом; кисти нейтральны.","mist":"Мах корпусом; подъём плеч; локти уходят вперёд; слишком короткая амплитуда."},{"code":"TRICEPS_STRAIGHT_BAR_PUSHDOWN","name":"Разгибание рук на верхнем блоке с прямой рукоятью","type":"isolation","track":"weight_reps","eq":"cable","pat":"elbow_extension","rest":75,"uni":false,"aliases":["Разгибание на трицепс с прямой рукоятью"],"p":["triceps"],"s":[],"st":[],"d":"Классическое разгибание локтя на блоке с фиксированной рукоятью. Простая альтернатива канату, если так удобнее держать локти и кисти.","i":"Держи локти около корпуса и разгибай руки вниз до контролируемого сокращения, затем медленно вернись.","setup":"Корпус устойчив; плечи опущены; хват комфортной ширины.","mist":"Локти уходят вперёд; движение всем корпусом; чрезмерно тяжёлый вес; заламывание кистей."},{"code":"TRICEPS_SINGLE_ARM_PUSHDOWN","name":"Разгибание одной руки на верхнем блоке","type":"isolation","track":"weight_reps","eq":"cable","pat":"elbow_extension","rest":60,"uni":true,"aliases":["Одноручное разгибание на трицепс"],"p":["triceps"],"s":[],"st":[],"d":"Одностороннее разгибание локтя, позволяющее свободно подобрать положение кисти и сравнивать стороны.","i":"Зафиксируй плечо у корпуса и полностью разгибай локоть без движения плечом. Возвращай вес до комфортного сгибания.","setup":"Можно использовать рукоять или ремень; корпус не поворачивается.","mist":"Ротация корпуса; локоть гуляет; рывок; слишком большой вес."},{"code":"TRICEPS_CLOSE_GRIP_BENCH","name":"Жим штанги лёжа узким хватом","type":"compound","track":"weight_reps","eq":"barbell","pat":"horizontal_push","rest":150,"uni":false,"aliases":["Узкий жим на трицепс"],"p":["triceps"],"s":["chest","delts_front"],"st":[],"d":"Многосуставной жим с повышенным вкладом трицепса. Полезен как тяжёлый вариант, но не является полной биомеханической заменой изолирующим разгибаниям.","i":"Опускай штангу к нижней части груди, удерживая локти ближе к корпусу, и выжимай вверх без отбива.","setup":"Хват примерно на ширине плеч или немного уже; кисти над предплечьями; лопатки стабильны.","mist":"Слишком узкий хват; локти сильно в стороны; отбив; чрезмерная нагрузка на кисти."},{"code":"QUAD_BACK_SQUAT","name":"Приседания со штангой на спине","type":"compound","track":"weight_reps","eq":"barbell","pat":"squat","rest":180,"uni":false,"aliases":["Присед со штангой"],"p":["quads","glutes"],"s":["hamstrings"],"st":["core","erectors"],"d":"Базовое многосуставное упражнение для квадрицепса и ягодиц. Техника сильно зависит от антропометрии, мобильности и удобной стойки.","i":"Сядь вниз между стопами, сохраняя устойчивую опору всей стопой и колени по направлению носков. Поднимайся, одновременно разгибая колени и таз.","setup":"Ширина стоп индивидуальна; штанга стабильно лежит на верхе спины; вдох и брейс перед повтором.","mist":"Колени заваливаются внутрь; потеря опоры пяткой; расслабление корпуса; глубина ниже контролируемой позиции."},{"code":"QUAD_SMITH_SQUAT","name":"Приседания в Смите","type":"compound","track":"weight_reps","eq":"smith","pat":"squat","rest":150,"uni":false,"aliases":["Присед в машине Смита"],"p":["quads","glutes"],"s":["hamstrings"],"st":["core"],"d":"Присед с фиксированной траекторией, позволяющий меньше думать о балансе и легче дозировать нагрузку на ноги.","i":"Расположи стопы так, чтобы в нижней точке сохранялась устойчивость, затем приседай до комфортной глубины и вставай без отрыва стоп.","setup":"Проверь положение стоп пустым грифом; спина нейтральна; колени движутся по линии носков.","mist":"Стопы стоят слишком близко к траектории грифа; колени внутрь; таз подворачивается с потерей контроля."},{"code":"QUAD_LEG_EXTENSION","name":"Разгибание ног в тренажёре","type":"isolation","track":"weight_reps","eq":"machine","pat":"knee_extension","rest":75,"uni":false,"aliases":["Разгибание коленей в тренажёре"],"p":["quads"],"s":[],"st":[],"d":"Изолирующее разгибание колена для квадрицепса. Удобно для прямой нагрузки на квадрицепс без ограничения со стороны спины и ягодиц.","i":"Разгибай колени плавно до почти полного выпрямления и медленно опускай вес, сохраняя таз прижатым.","setup":"Ось колена совпадает с осью тренажёра; валик расположен над нижней частью голени.","mist":"Рывок; отрыв таза; бросание веса вниз; слишком большая нагрузка с потерей контроля."},{"code":"QUAD_REVERSE_LUNGE","name":"Обратные выпады с гантелями","type":"compound","track":"weight_reps","eq":"dumbbell","pat":"lunge","rest":120,"uni":true,"aliases":["Выпады назад"],"p":["quads","glutes"],"s":["hamstrings"],"st":["core"],"d":"Одностороннее упражнение на квадрицепс и ягодицы, обычно легче контролируемое, чем выпады вперёд. Хорошо подходит для сравнения сторон.","i":"Шагни назад, опусти колено к полу и вернись усилием передней ноги. Держи переднюю стопу полностью на полу.","setup":"Ширина шага должна позволять сохранять баланс и колено по линии стопы.","mist":"Отталкивание задней ногой; завал колена внутрь; слишком узкая линия стоп; падение корпуса."},{"code":"QUAD_WALKING_LUNGE","name":"Выпады в движении с гантелями","type":"compound","track":"weight_reps","eq":"dumbbell","pat":"lunge","rest":120,"uni":true,"aliases":["Ходьба выпадами"],"p":["quads","glutes"],"s":["hamstrings"],"st":["core"],"d":"Динамический односторонний вариант для ног и ягодиц, одновременно требующий координации и устойчивости.","i":"Сделай контролируемый шаг, опусти заднее колено и перенеси корпус вперёд в следующий выпад через усилие передней ноги.","setup":"Держи гантели вдоль корпуса; шаги одинаковой длины; сохраняй пространство между стопами по ширине.","mist":"Шаги по одной линии; колено внутрь; толчок задней ногой; слишком быстрый темп."},{"code":"HAMSTRING_RDL_BB","name":"Румынская тяга со штангой","type":"compound","track":"weight_reps","eq":"barbell","pat":"hinge","rest":180,"uni":false,"aliases":["Румынская тяга"],"p":["hamstrings","glutes"],"s":[],"st":["core","erectors"],"d":"Базовый тазовый шарнир для задней поверхности бедра и ягодиц. Хорошо прогрессируется по весу и нагружает мышцы в растянутом положении.","i":"Отводи таз назад при слегка согнутых коленях и веди штангу близко к ногам. Остановись там, где сохраняется нейтральная спина и выраженное растяжение задней поверхности бедра, затем разогни таз.","setup":"Стопы примерно на ширине таза; хват чуть шире ног; корпус собран.","mist":"Присед вместо наклона; штанга далеко от ног; округление спины; попытка обязательно коснуться пола."},{"code":"HAMSTRING_NORDIC_CURL","name":"Нордические сгибания","type":"isolation","track":"bodyweight_reps","eq":"bodyweight","pat":"knee_flexion","rest":120,"uni":false,"aliases":["Nordic curl"],"p":["hamstrings"],"s":[],"st":["core"],"d":"Тяжёлое сгибание колена собственным весом с большой эксцентрической нагрузкой на заднюю поверхность бедра. Подходит, если можно надёжно зафиксировать стопы.","i":"Сохраняя прямую линию от коленей до головы, медленно опускай корпус вперёд, сопротивляясь разгибанию коленей. Помоги руками внизу и вернись настолько активно, насколько позволяет сила.","setup":"Колени на мягкой опоре; пятки надёжно зафиксированы партнёром или оборудованием.","mist":"Сгибание в тазу; слишком быстрое падение; чрезмерный объём для неподготовленного клиента; ненадёжная фиксация стоп."},{"code":"GLUTE_HIP_THRUST_BB","name":"Ягодичный мост со штангой от скамьи","type":"compound","track":"weight_reps","eq":"barbell","pat":"hip_thrust","rest":150,"uni":false,"aliases":["Hip thrust со штангой","Хип-траст"],"p":["glutes"],"s":["hamstrings"],"st":["core"],"d":"Стабильное упражнение для целевой нагрузки большой ягодичной. Хорошо прогрессируется по весу и обычно мало ограничивается спиной.","i":"Опирайся верхом спины на скамью, опусти таз и разогни его до положения, где корпус и бедро образуют линию. Вверху слегка подкрути таз без переразгибания поясницы.","setup":"Гриф лежит на сгибе таза через мягкую накладку; стопы стоят так, чтобы вверху голени были близки к вертикали.","mist":"Переразгибание поясницы; стопы слишком далеко или близко; толчок носками; неполная нижняя амплитуда."},{"code":"GLUTE_HIP_THRUST_SMITH","name":"Ягодичный мост в Смите от скамьи","type":"compound","track":"weight_reps","eq":"smith","pat":"hip_thrust","rest":120,"uni":false,"aliases":["Hip thrust в Смите"],"p":["glutes"],"s":["hamstrings"],"st":["core"],"d":"Стабильный вариант hip thrust с фиксированной траекторией. Удобен для самостоятельной тренировки и работы близко к отказу.","i":"Опусти таз под контролем и разогни до полного сокращения ягодиц без прогиба поясницы. Сохраняй колени по линии стоп.","setup":"Скамья надёжно зафиксирована; гриф с мягкой накладкой; стопы симметричны.","mist":"Скамья скользит; переразгибание поясницы; колени внутрь; движение слишком короткое."},{"code":"GLUTE_CABLE_KICKBACK","name":"Отведение ноги назад на нижнем блоке","type":"isolation","track":"weight_reps","eq":"cable","pat":"hip_extension","rest":60,"uni":true,"aliases":["Кикбэк на ягодицы в кроссовере"],"p":["glutes"],"s":["hamstrings"],"st":["core"],"d":"Одностороннее разгибание бедра с постоянным сопротивлением троса. Подходит для дополнительной нагрузки ягодиц без тяжёлой осевой нагрузки.","i":"Сохраняя таз направленным вперёд, отводи бедро назад до сокращения ягодицы и медленно возвращай ногу.","setup":"Манжета на голени или лодыжке; корпус стабилен; опорная нога слегка согнута.","mist":"Прогиб поясницы; разворот таза; мах ногой; слишком большая амплитуда."},{"code":"GLUTE_BACK_EXTENSION_45","name":"Гиперэкстензия 45° с акцентом на ягодицы","type":"compound","track":"weight_reps","eq":"machine","pat":"hip_extension","rest":90,"uni":false,"aliases":["Гиперэкстензия на ягодицы"],"p":["glutes"],"s":["hamstrings"],"st":["erectors"],"d":"Разгибание таза на римском стуле с акцентом на ягодицы и заднюю поверхность бедра. Удобный дополнительный вариант без тяжёлой штанги.","i":"Отводи таз назад и опускай корпус за счёт тазобедренного сустава. Поднимайся сокращением ягодиц до нейтрального положения корпуса.","setup":"Край подушки находится ниже сгиба таза; стопы надёжно зафиксированы.","mist":"Переразгибание поясницы; движение позвоночником вместо таза; слишком высокая подушка; рывки."},{"code":"GLUTE_MACHINE_ABDUCTION","name":"Отведение бёдер в тренажёре","type":"isolation","track":"weight_reps","eq":"machine","pat":"hip_abduction","rest":60,"uni":false,"aliases":["Разведение ног в тренажёре"],"p":["glutes_medius"],"s":["glutes"],"st":[],"d":"Изолированное отведение бедра для средней ягодичной и других отводящих мышц. Не является обязательным для каждой программы, но удобно как дополнительная работа.","i":"Разводи бёдра плавно до комфортной амплитуды и медленно возвращай, сохраняя таз устойчивым.","setup":"Сядь устойчиво; настрой упоры так, чтобы движение начиналось без болезненного растяжения.","mist":"Рывки; чрезмерный наклон корпуса ради веса; быстрое схлопывание ног; слишком большая амплитуда."},{"code":"LEGS_MACHINE_ADDUCTION","name":"Приведение бёдер в тренажёре","type":"isolation","track":"weight_reps","eq":"machine","pat":"hip_adduction","rest":60,"uni":false,"aliases":["Сведение ног в тренажёре"],"p":["adductors"],"s":[],"st":[],"d":"Изолированное приведение бедра для приводящих мышц. Полезно как дополнительное упражнение, если в программе нужен прямой объём на внутреннюю поверхность бедра.","i":"Своди бёдра плавно до комфортного сокращения и медленно возвращай их наружу без рывка.","setup":"Настрой стартовую ширину так, чтобы не было болезненного растяжения в паху.","mist":"Резкое растяжение; бросание веса; чрезмерная стартовая ширина; отрыв таза от сиденья."},{"code":"CALVES_SINGLE_LEG_DB","name":"Подъём на носок одной ногой с гантелью","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"calf_raise","rest":60,"uni":true,"aliases":["Одноногий подъём на носок"],"p":["calves"],"s":[],"st":[],"d":"Доступный вариант тренировки икр с почти прямым коленом, не требующий специального тренажёра. Позволяет отдельно сравнивать силу сторон.","i":"Опускай пятку до комфортного растяжения и поднимайся максимально высоко на носок без пружинящих движений.","setup":"Передняя часть стопы на устойчивой платформе; свободной рукой можно держаться за опору.","mist":"Пружинящий темп; сгибание колена; разворот стопы; сокращённая амплитуда."},{"code":"CORE_PLANK","name":"Планка на предплечьях","type":"isolation","track":"duration","eq":"bodyweight","pat":"core_anti_extension","rest":60,"uni":false,"aliases":["Планка"],"p":["core"],"s":[],"st":["glutes"],"d":"Изометрическое упражнение на сопротивление разгибанию поясницы. Подходит для базового контроля корпуса и не требует оборудования.","i":"Сожми ягодицы, слегка подкрути таз и удерживай рёбра над тазом. Дыши, не теряя положения корпуса.","setup":"Локти под плечами; ноги прямые; тело образует ровную линию.","mist":"Провисание поясницы; слишком высокий таз; задержка дыхания; перенос нагрузки только на плечи."},{"code":"CORE_HANGING_KNEE_RAISE","name":"Подъём коленей в висе","type":"compound","track":"reps_only","eq":"bodyweight","pat":"core_hip_flexion","rest":75,"uni":false,"aliases":["Подъём коленей к груди в висе"],"p":["core"],"s":[],"st":["forearms"],"d":"Подъём таза и коленей в висе, нагружающий мышцы живота и сгибатели бедра. Удобен для прогрессии к подъёму прямых ног.","i":"Начни без раскачки, подними колени и в конце слегка подкрути таз вверх. Медленно опусти ноги, сохраняя контроль.","setup":"Хват надёжный; плечи активны; корпус не раскачивается.","mist":"Маятник ногами; движение только бедром без подкручивания таза; быстрый сброс ног; потеря хвата."},{"code":"CORE_AB_WHEEL","name":"Роллаут с колесом для пресса","type":"compound","track":"reps_only","eq":"other","pat":"core_anti_extension","rest":90,"uni":false,"aliases":["Колесо для пресса","Ab wheel"],"p":["core"],"s":["lats"],"st":["glutes"],"d":"Сложное динамическое упражнение на сопротивление разгибанию позвоночника. Хорошо прогрессируется увеличением длины выката.","i":"Сохраняя таз слегка подкрученным, выкатывай колесо вперёд настолько далеко, насколько можешь удержать поясницу, затем вернись за счёт пресса и плечевого пояса.","setup":"Начинай с коленей; поверхность не скользкая; колесо движется прямо.","mist":"Провисание поясницы; слишком дальний выкат; возврат только руками; потеря контроля таза."},{"code":"CORE_DEAD_BUG","name":"Dead bug","type":"isolation","track":"reps_only","eq":"bodyweight","pat":"core_anti_extension","rest":45,"uni":true,"aliases":["Мёртвый жук"],"p":["core"],"s":[],"st":[],"d":"Контрольное упражнение на удержание поясницы и таза при движении рук и ног. Полезно для обучения брейсингу перед более тяжёлыми упражнениями.","i":"Прижми поясницу к полу, медленно разгибай противоположные руку и ногу и возвращай их, не теряя положения таза.","setup":"Бёдра и колени около 90°; руки вверх; дыхание спокойное.","mist":"Поясница отрывается; движение слишком быстрое; чрезмерная амплитуда; напряжение шеи."},{"code":"TRAPS_SHRUG_BB","name":"Шраги со штангой","type":"isolation","track":"weight_reps","eq":"barbell","pat":"shrug","rest":90,"uni":false,"aliases":["Шраги со штангой стоя"],"p":["traps"],"s":[],"st":["forearms"],"d":"Простой тяжёлый вариант подъёма лопаток для верхней трапеции. Легко прогрессируется по нагрузке.","i":"Поднимай плечи вертикально вверх, задержись на мгновение и медленно опускай. Руки остаются прямыми.","setup":"Штанга перед бёдрами; хват удобной ширины; шея нейтральна.","mist":"Круговые движения плечами; сгибание локтей; рывки; запрокидывание головы."},{"code":"BACK_EXTENSION_45","name":"Гиперэкстензия 45° с акцентом на разгибатели спины","type":"compound","track":"weight_reps","eq":"machine","pat":"back_extension","rest":90,"uni":false,"aliases":["Гиперэкстензия на спину"],"p":["erectors"],"s":["glutes","hamstrings"],"st":["core"],"d":"Разгибание корпуса на римском стуле с акцентом на разгибатели позвоночника. Используется как дополнительная работа для задней цепи.","i":"Сохраняй контролируемую нейтральную позицию позвоночника, опускай корпус и поднимайся до линии с ногами без переразгибания.","setup":"Подушка позволяет свободно сгибаться в тазобедренном суставе; стопы надёжно зафиксированы.","mist":"Рывки; переразгибание вверху; чрезмерное округление под нагрузкой; слишком большая амплитуда."},{"code":"FOREARMS_WRIST_CURL","name":"Сгибание кистей с гантелями","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"wrist_flexion","rest":60,"uni":false,"aliases":["Сгибание запястий на предплечья"],"p":["forearms"],"s":[],"st":[],"d":"Изолирующее сгибание запястья для мышц-сгибателей предплечья. Используется как дополнительное упражнение, если хвата и тяг недостаточно.","i":"Зафиксируй предплечья на бедре или скамье и двигай только кистями, медленно опуская вес до растяжения.","setup":"Кисти свободно выходят за край опоры; вес умеренный.","mist":"Движение локтями; рывки; слишком большой вес; чрезмерное разгибание запястья."},{"code":"FOREARMS_REVERSE_WRIST_CURL","name":"Разгибание кистей с гантелями","type":"isolation","track":"weight_reps","eq":"dumbbell","pat":"wrist_extension","rest":60,"uni":false,"aliases":["Обратные сгибания кистей"],"p":["forearms"],"s":[],"st":[],"d":"Изолирующее разгибание запястья для мышц-разгибателей предплечья. Полезно как дополнительная работа для баланса мышц предплечья.","i":"Зафиксируй предплечья и поднимай тыльную сторону кисти вверх, затем медленно опускай.","setup":"Предплечья лежат на опоре; ладони направлены вниз; вес небольшой.","mist":"Подъём предплечий; рывки; слишком тяжёлый вес; чрезмерная амплитуда."}]'::jsonb) as x(code text,p jsonb,s jsonb,st jsonb)
), roles as (
  select code,jsonb_array_elements_text(p) muscle,'primary' role from data
  union all select code,jsonb_array_elements_text(s),'secondary' from data
  union all select code,jsonb_array_elements_text(st),'stabilizer' from data
)
insert into public.exercise_muscle_groups(exercise_id,muscle_group_code,role)
select e.id,r.muscle,r.role
from roles r join public.exercises e using(code)
on conflict(exercise_id,muscle_group_code) do update set role=excluded.role;

-- Переименовываем старую группу без смены UUID, чтобы не рвать возможные ссылки программ.
update public.exercise_substitution_groups
set code='CHEST_INCLINE_PRESS',name='Наклонные жимы на грудь',
    purpose='Близкие варианты наклонного жима: гантели, штанга, Смит и тренажёр.'
where code='CHEST_UPPER_PRESS'
  and not exists(select 1 from public.exercise_substitution_groups where code='CHEST_INCLINE_PRESS');

with data as (
  select *
  from jsonb_to_recordset('[{"code":"CHEST_PRESS","name":"Все жимы на грудь","purpose":"Широкая группа жимов на грудь для режима широкой замены.","scope":"broad","parent":null},{"code":"CHEST_INCLINE_PRESS","name":"Наклонные жимы на грудь","purpose":"Близкие варианты наклонного жима: гантели, штанга, Смит и тренажёр.","scope":"specific","parent":"CHEST_PRESS"},{"code":"CHEST_FLAT_PRESS","name":"Горизонтальные жимы на грудь","purpose":"Близкие варианты горизонтального жима.","scope":"specific","parent":"CHEST_PRESS"},{"code":"CHEST_FLY","name":"Сведения на грудь","purpose":"Изолирующие варианты сведения рук на грудь.","scope":"specific","parent":null},{"code":"BACK_VERTICAL_PULL","name":"Вертикальные тяги","purpose":"Варианты верхнего блока и подтягиваний; хваты взаимозаменяемы по удобству.","scope":"specific","parent":null},{"code":"BACK_HORIZONTAL_ROW","name":"Горизонтальные тяги","purpose":"Варианты горизонтальной тяги для середины спины.","scope":"specific","parent":null},{"code":"BACK_LAT_ISOLATION","name":"Изоляция широчайших","purpose":"Разгибание плеча с минимальным вкладом сгибателей локтя.","scope":"specific","parent":null},{"code":"SHOULDER_PRESS","name":"Вертикальные жимы на плечи","purpose":"Гантели, штанга, Смит и тренажёры для вертикального жима.","scope":"specific","parent":null},{"code":"DELTS_SIDE_RAISE","name":"Отведения на среднюю дельту","purpose":"Изолирующие варианты отведения плеча.","scope":"specific","parent":null},{"code":"DELTS_REAR","name":"Задняя дельта","purpose":"Разведения и тяговые варианты с акцентом на заднюю дельту.","scope":"specific","parent":null},{"code":"BICEPS_CURL","name":"Сгибания на бицепс","purpose":"Основные варианты сгибания локтя; молотки допустимы как близкая альтернатива.","scope":"specific","parent":null},{"code":"TRICEPS_EXTENSION","name":"Упражнения на трицепс","purpose":"Широкая группа упражнений на трицепс.","scope":"broad","parent":null},{"code":"TRICEPS_PUSHDOWN","name":"Разгибания вниз на блоке","purpose":"В