AISE","code":"CORE_HANGING_KNEE_RAISE","priority":10},{"group":"TRAPS_ELEVATION","code":"TRAPS_SHRUG_DB","priority":10},{"group":"TRAPS_ELEVATION","code":"TRAPS_SHRUG_SMITH","priority":20},{"group":"TRAPS_ELEVATION","code":"TRAPS_SHRUG_BB","priority":30},{"group":"TRAPS_ELEVATION","code":"TRAPS_FARMER_WALK","priority":40},{"group":"BACK_EXTENSION","code":"BACK_EXTENSION_45","priority":10},{"group":"FOREARM_WRIST_FLEXION","code":"FOREARMS_WRIST_CURL","priority":10},{"group":"FOREARM_WRIST_EXTENSION","code":"FOREARMS_REVERSE_WRIST_CURL","priority":10}]'::jsonb) as x("group" text,code text,priority integer)
