insert into public.exercise_substitution_members(group_id,exercise_id,priority,is_default,match_type,notes)
select g.id,e.id,d.priority,(d.priority=10),
  case
    when d."group"='DELTS_REAR' and d.code='DELTS_REAR_FACE_PULL' then 'acceptable'
    when d."group"='BICEPS_CURL' and d.code='BICEPS_HAMMER_CURL' then 'acceptable'
    when d."group"='TRAPS_ELEVATION' and d.code='TRAPS_FARMER_WALK' then 'fallback'
    else 'direct'
  end,
  null
from data d
join public.exercise_substitution_groups g on g.code=d."group"
join public.exercises e on e.code=d.code
on conflict(group_id,exercise_id) do update set
  priority=excluded.priority,is_default=excluded.is_default,match_type=excluded.match_type,notes=excluded.notes;

-- Public exercise thumbnails: files in Storage, only metadata in Postgres.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('exercise-media','exercise-media',true,2097152,array['image/jpeg','image/png','image/webp'])
on conflict(id) do update set
  public=true,file_size_limit=2097152,allowed_mime_types=array['image/jpeg','image/png','image/webp'];

drop policy if exists "exercise_media_storage_insert_trainer" on storage.objects;
create policy "exercise_media_storage_insert_trainer"
on storage.objects for insert to authenticated
with check (
  bucket_id='exercise-media'
  and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='trainer')
);

drop policy if exists "exercise_media_storage_delete_trainer" on storage.objects;
create policy "exercise_media_storage_delete_trainer"
on storage.objects for delete to authenticated
using (
  bucket_id='exercise-media'
  and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='trainer')
);

grant select on public.exercise_media to anon;
drop policy if exists exercise_media_preview_read on public.exercise_media;
create policy exercise_media_preview_read on public.exercise_media
for select to anon using (kind='image');

-- Existing incline chest exercises now point to plain "Грудь".
update public.exercises
set muscle_group='Грудь',updated_at=now()
where code in ('CHEST_UPPER_DB_PRESS','CHEST_UPPER_BB_PRESS','CHEST_UPPER_SMITH_PRESS');
